programs.haiku:
"""Mid-word tokens: a weak, mostly-negative activation on subword pieces of split words.

layers.0.mlp.down_proj:1920 is a rank-one piece of layer 0's MLP output. Its activation is
small and sparse. Across the harvested windows it is most negative on the later pieces of
words and names that the tokenizer split (e.g. "lid|ens|kap", "Sax|ony"), and mildly positive
on punctuation. This program predicts that pattern from the current token and the one before it:
  - a token that continues a word (letters, no leading space)      -> negative
  - a continuation directly after another continuation             -> partly cancels
  - punctuation                                                    -> mildly positive
Otherwise it predicts 0. It has no memory beyond the previous token.
"""

READS = ()


def _is_word_piece(s):
    return bool(s) and not s[0].isspace() and s.strip().isalpha()


def _is_punct(s):
    return bool(s.strip()) and not any(ch.isalnum() for ch in s)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix) > 1 else ""
    value = -0.0025
    if _is_word_piece(token):
        value -= 0.01
        if _is_word_piece(previous):
            value += 0.008
    elif _is_punct(token):
        value += 0.008
    return carry, float(value)

"""Sentence-final full stops in the layer-0 MLP (layers.0.mlp.down_proj, component 1921).

The component is a "full stop" detector whose sign depends on what the stop closes. On a
plain "." the value is a sum of two terms. The word before the stop: a digit ("1.", decimals)
pushes it positive, a long lowercase word (the usual end of a sentence) pushes it most
negative, short words and capitalised abbreviations sit in between, and a single letter is
neutral. The gap since the previous stop: a stop soon after the last one (under 10 tokens, as
in abbreviations, initials and list items) is positive, while a stop closing a normal-length
sentence (20 to 80 tokens after the last stop) is negative. Stops glued to a newline, a
closing quote or bracket are about -0.4 (-0.15 after a digit); Chinese/Japanese stops (。)
are -0.9 (-0.55 with a newline); "?" is -0.27 and "!" -0.09. Other tokens, including
code-like ".py" or "...", are 0. The only context read is the word before the stop and the
tokens since the last stop in the same document, carried from step to step as the gap."""

READS = ()

CLOSING_STOPS = {".\n", ".\n\n", ").", ").\n", ").\n\n", '."', '".', ".”", ".”\n", "$.", ".\\"}
CJK_STOPS = {"。": -0.9, "。\n": -0.55}
WORD_TERM = {"digit": 0.6, "single": 0.0, "capital": -0.1, "short": -0.15, "long": -0.5}


def word_kind(word):
    if word[-1:].isdigit():
        return "digit"
    if len(word) == 1:
        return "single"
    if word[:1].isupper():
        return "capital"
    if len(word) <= 3:
        return "short"
    return "long"


def gap_term(gap):
    if gap < 5:
        return 0.6
    if gap < 10:
        return 0.45
    if gap < 20:
        return 0.1
    if gap < 40:
        return -0.35
    if gap < 80:
        return -0.5
    return -0.4


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]
    gap = 999 if (carry is None or new_doc) else carry  # tokens since the last stop
    word = "" if new_doc else prefix.token_strings[-2].strip()
    is_stop = tok == "." or tok in CJK_STOPS or tok in CLOSING_STOPS
    next_gap = 1 if is_stop else gap + 1
    if tok in CJK_STOPS:
        return next_gap, CJK_STOPS[tok]
    if tok == "?":
        return next_gap, -0.27
    if tok == "!":
        return next_gap, -0.09
    if tok in CLOSING_STOPS:
        return next_gap, -0.15 if word[-1:].isdigit() else -0.4
    if tok == "." and not new_doc:
        return next_gap, WORD_TERM[word_kind(word)] + gap_term(gap)
    return next_gap, 0.0

programs.luna:
"""Periods usually contribute a little negatively. A period at the start
of a packed row is strongly positive, as is one immediately after a digit;
the full-width Japanese stop is more negative. Other tokens are silent.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "." not in token and "。" not in token:
        return None, 0.0

    previous = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if token.startswith(".") and previous and previous[-1].isdigit():
        return None, 0.25

    if "。" in token:
        return None, -0.62

    if prefix.position == 0:
        return None, 1.0

    if token.rstrip().endswith((")", '"', "”")):
        return None, -0.5

    return None, -0.3

programs.sol:
"""Local programming-syntax cues: null-like values, backslash escapes,
and names after member-access punctuation or command-option dashes.

Whitespace/quotes before a dash strengthen the response; a dash inside a
word is weaker. Literal nulls are stronger than null comparisons. Joined
'.name' tokens do not get the response of a separately tokenized dot.
Paths (especially workspace paths) and signed numeric literals get smaller
responses. Unmatched tokens get zero; state resets between documents.
This is a coarse rule, not a list of individual token activations.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.lstrip(' \t\r\n(),=/|._-:')
    comparison = prev.strip() in ('==', '!=', '===', '!==')
    value = 0.0

    if word.lower() == 'null':
        if token.startswith((' ', '\t')) or token == word:
            value = 0.86 if comparison else 1.23
            if word == 'NULL':
                value = 0.75 if comparison else 0.94
        else:
            value = 1.0
    elif word.lower() == 'nil':
        value = 0.57 if comparison else 0.73
        if token != word and not token[0].isspace():
            value = 0.61
    elif word == 'nullptr':
        value = 0.65
    elif word == 'None':
        value = 0.4 if token.startswith('=') else 0.22
    elif word.lower() == 'nullable' or word.endswith(('IsNull', 'OrNull')):
        value = 0.5
    elif token == '\\n':
        value = 0.64 if prev in ('n', '\\n', '\\t') else 0.71
    elif token == '\\t':
        value = 0.54 if prev == '\\t' else 0.49
    elif token == '\\r':
        value = 0.47
    elif token.startswith('\\') and token[1:].isalpha():
        value = 0.13
    elif token.isascii() and token.isalpha():
        lower = token.islower()
        if prev.endswith(('.', '._', '.__')):
            if prev.endswith('..'):
                value = 0.12
            elif prev.endswith('_'):
                value = 0.25
            else:
                value = 0.56 if lower else 0.32
                if prev == '.':
                    value -= 0.12
        elif prev.endswith('::'):
            value = 0.47 if lower else 0.22
        elif prev.endswith('->'):
            value = 0.37 if lower else 0.26
        elif prev.endswith('-') and not prev.endswith(('<-', '---')):
            if any(c in prev for c in '\'"`'):
                value = 0.65
            elif prev.startswith(' '):
                value = 0.61 if lower or len(token) == 1 else 0.25
                if token in ('x', 'y', 'z', 't'):
                    value = 0.3
            else:
                value = 0.18 if lower or len(token) == 1 else 0.09
        elif prev.endswith('/') and lower:
            if token == 'workspace':
                value = 0.65 if prev.startswith(' ') else 0.5
            else:
                value = 0.16 if prev.startswith(' ') else 0.04
    elif token.isdigit() and prev.endswith('-'):
        if '`' in prev:
            value = 0.7
        elif prev.endswith('[-'):
            value = 0.31
        elif prev.endswith('{-'):
            value = 0.24
        elif prev.endswith(('(-', '=-', ',-')):
            value = 0.15
        elif prev == ' -':
            value = 0.11

    return (doc, token), float(value)

programs.luna:
"""Mark syntax boundaries and give extra weight to empty values in expressions."""

READS = ()

EMPTY_VALUES = {"null", "nil", "none", "undefined"}
OPERATORS = {"=", "==", "!=", "|", "or"}
SEPARATORS = set("-+*/%=!<>|&:.,;[({})]")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if word in EMPTY_VALUES:
        if prefix.position and (
            prefix.document_ids[-1] == prefix.document_ids[-2]
        ):
            previous = prefix.token_strings[-2].strip().lower()
            if previous in OPERATORS:
                return None, 0.25
        return None, 0.03
    if token in ("\n", "\t"):
        return None, 0.03

    piece = token.lstrip()
    starts_code_boundary = piece.startswith(("\\", "."))
    if starts_code_boundary:
        piece = piece[1:]
    if not piece or not (piece[0].isalnum() or piece[0] == "_"):
        return None, 0.0
    if starts_code_boundary:
        return None, 0.03

    if prefix.position and (
        prefix.document_ids[-1] == prefix.document_ids[-2]
    ):
        previous = prefix.token_strings[-2].rstrip()
        if previous and previous[-1] in SEPARATORS:
            return None, 0.03
    return None, 0.0

programs.haiku:
"""Where-is-it prepositions: a locative word right after a verb of being located or placed.

This component writes a "where is it" signal into the residual stream. It fires on a
locative word ("in", "on", "at", "within", "outside", "along", "under", "across"; Chinese
在 and 于) when the word just before is a verb of position or existence: "located in"
(about 4.5), "stored in", "present in", "sitting on", "lies on", "placed on", "found in",
"lived in", "born in", "resides in", "remain in". Other participles and a form of "be" give
a weaker signal ("shown in", "is in", about 0.5). Locatives after verbs of speaking, asking
or helping ("called on", "advice on", "help with") go slightly negative. After a position
verb, the words "here", "there", "below", "as", "therein" and "invention" (as in "present
invention") also fire, about 1. Every other token predicts 0.
"""

READS = ()

LOCATIVE = {"in", "on", "at", "within", "outside", "inside", "along", "under", "across",
            "在", "于"}
AFTER_PLACEMENT = {"here", "there", "below", "above", "onto", "therein", "as", "with",
                   "between", "around", "invention"}
PLACEMENT = {
    "located", "stored", "housed", "placed", "place", "placing", "lies", "lie", "lay",
    "lying", "lain", "resting", "sit", "sits", "sitting", "sat", "stand", "stands",
    "standing", "stood", "displayed", "listed", "available", "included", "recorded",
    "present", "born", "stay", "stays", "stayed", "staying", "kept", "situated", "found",
    "contained", "reside", "resides", "residing", "live", "lived", "lives", "living",
    "mounted", "centered", "centred", "remains", "remain", "disposed", "stationed",
    "buried", "posted", "published", "appeared", "appear", "appears", "exist", "exists",
    "occur", "occurs", "arise", "served", "shown", "written", "presented", "hidden",
    "rooted", "positioned", "position", "embedded", "settle", "settled", "confined",
    "immersed", "store",
}
NEGATIVE = {
    "call", "called", "calls", "help", "helps", "helped", "assistance", "advice", "reply",
    "said", "say", "take", "took", "make", "made", "want", "decide", "ask", "asked", "tell",
    "told",
}
BE_FORMS = {"is", "are", "was", "were", "be", "been", "being", "am"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    word = _word(prefix.token_strings[-1])
    before = _word(prefix.token_strings[-2])
    if word in AFTER_PLACEMENT and before in PLACEMENT:
        return None, 1.0
    if word not in LOCATIVE:
        return None, 0.0
    if before in PLACEMENT:
        return None, 2.5
    if before in NEGATIVE:
        return None, -0.6
    if before in BE_FORMS:
        return None, 0.6
    if before.endswith(("ed", "ing")):
        return None, 0.5
    return None, 0.1

programs.sol:
"""Approximate local qualifier responses and empty-reasoning boundaries.

Training examples showed positive activations after novelty, legal, social
and technical qualifiers, and negative blank lines around empty reasoning
blocks. The latter are stronger with recent Han-character text. Chat/tool
markers have fitted offsets, as do the phrases "according to" and "referred
to". Unrecognized tokens receive a near-zero background.

This is a partial explanation: a larger per-word table adds grammatical-word,
punctuation and digit offsets, but this version leaves those lexical details
unmodeled. All context is causal and resets at document boundaries.
"""
from collections import deque

READS = ()

QUALIFIERS = {
    'new': 0.030, 'modern': 0.025,
    'private': 0.027, 'public': 0.023, 'general': 0.030,
    'legal': 0.115, 'civil': 0.080, 'social': 0.075,
    'medical': 0.060, 'electronic': 0.150, 'digital': 0.080,
    'electrical': 0.070, 'technical': 0.080,
    'professional': 0.065, 'special': 0.050, 'basic': 0.055,
    'standard': 0.030, 'business': 0.055, 'universal': 0.050,
    'personal': 0.030, 'financial': 0.040, 'economic': 0.080,
    '新': 0.220, '的新': 0.200,
    '专': 0.380, '專': 0.090, '私': 0.095, '公': 0.085,
    '专业': 0.110, '專業': 0.060, '基本': 0.075,
}
MARKERS = {
    '<think>': 0.047, '</think>': 0.100,
    '<tool_call>': 0.134, '</tool_call>': 0.032,
    '<tool_response>': 0.038, '</tool_response>': -0.073,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', deque(maxlen=64), False)
    _, previous, history, empty_thought = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = MARKERS.get(token, 0.001)
    if word and word[0].isalpha():
        value += QUALIFIERS.get(previous.strip().lower(), 0.0)
    if word == 'to' and previous.strip().lower() in {'according', 'referred'}:
        value += 0.088
    if previous == '</tool_response>':
        value -= 0.091
    elif previous == '</tool_call>':
        value -= 0.049
    if token == '<|im_start|>':
        value = 0.037 if not previous or previous == '<|endoftext|>' else -0.039
    elif token == 'assistant' and previous == '<|im_start|>':
        value = 0.024
    elif token == '\n\n':
        chinese = sum(c for c, letters in history)
        letters = sum(letters for c, letters in history)
        ratio = chinese / max(1, letters)
        if previous == '<think>':
            value = -0.065 - 0.125 * ratio
        elif previous == '</think>' and empty_thought:
            value = -0.153 - 0.183 * ratio
        else:
            value = -0.003
    elif token == '\n':
        value = -0.020 if previous == 'assistant' else 0.003
    if token == '<think>':
        empty_thought = True
    elif token not in {'</think>', '\n\n'} and token.strip():
        empty_thought = False
    if not token.startswith('<'):
        chinese = sum('\u4e00' <= c <= '\u9fff' for c in token)
        letters = min(20, sum(c.isalpha() for c in token))
        history.append((min(10, chinese), letters))
    else:
        history.append((0, 0))
    return (doc, token, history, empty_thought), float(value)

programs.haiku:
"""Word-final consonant+"y" detector for layers.0.mlp.down_proj:1927.

This component goes negative on the letter "y" when it closes a short token after
a consonant: "by", "my", "any", "very", "many", "try", "baby", "cy", "xy", "ry", "y".
The more letters the token has, the weaker the response: whole long words such as
"property" or "community" stay near zero. Tokens ending in a vowel plus "y"
("day", "may", "they", "only") and tokens with no "y" at the end stay near zero.

The program reads only the newest token, decodes it alone, and returns a value
set by three tiers of token length.
"""

READS = ()

VOWELS = set("aeiou")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = 0.0
    if word.endswith("y"):
        before = word[-2] if len(word) >= 2 else ""
        if before not in VOWELS:
            if len(word) <= 3:
                value = -1.8
            elif len(word) <= 5:
                value = -1.2
            elif len(word) <= 7:
                value = -0.6
            else:
                value = -0.2
    return carry, float(value)

programs.luna:
"""Recognize software/tool names and adjacent fragments of those names.

The component's strongest recurring response is a negative pulse on software and
developer-ecosystem terms. A one-word carry joins token pieces into the current word;
it resets whenever a word boundary or a new document begins.
"""

READS = ()

SOFTWARE = {
    "apache", "apt", "cargo", "conda", "curl", "django", "doctrine", "docker",
    "ember", "eslint", "firebug", "flask", "git", "github", "gitlab", "helm",
    "illuminate", "jenkins", "laravel", "magento", "kubernetes", "node", "npm",
    "pandas", "pip", "pytorch", "raspberry", "react", "redis", "serde", "setuptools",
    "springframework", "sqlite", "tensorflow", "tinymce", "webpack", "wordpress", "yarn",
}
LANGUAGES = {"golang", "java", "javascript", "php", "python", "ruby", "rust", "typescript"}
PLATFORMS = {
    "amazon", "android", "aws", "chrome", "cloud", "linux", "macos", "ubuntu",
    "windows", "twitter",
}
DEV_SHORT = {"cli", "docs", "repo", "repos"}
DEV_TERMS = {"documentation", "framework", "package", "packages", "repository", "requirements"}
PUNCTUATION = " ./\\_-#()[]{}:;\"'<>`\t\r\n"


def _last_word(text):
    text = text.rstrip(PUNCTUATION)
    word = ""
    for char in reversed(text):
        if not char.isalnum():
            break
        word = char + word
    return word


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    piece = prefix.token_strings[-1].lower()
    previous = ""
    if carry is not None and carry[0] == document and piece and piece[0].isalnum():
        previous = carry[1]

    joined = previous + piece
    word = _last_word(joined)
    tail = word if piece and piece[-1].isalnum() else ""

    if word in SOFTWARE:
        value = -0.85
    elif word in PLATFORMS:
        value = -0.55
    elif word in LANGUAGES:
        value = -0.22
    elif word in DEV_SHORT:
        value = -0.65
    elif word in DEV_TERMS:
        value = -0.25
    else:
        value = 0.0
    return (document, tail), value

programs.sol:
"""Approximate the component's dominant hyphen/dash-boundary response.

Letter-leading segments are positive, with smaller carryover onto their next
subword. Familiar compound prefixes, chained compounds and age expressions
attenuate that pulse. Digits and isolated spaces after a dash are negative;
small nonzero digits are stronger. Space-prefixed words stay near zero, while
Markdown formatting can be strongly negative. The standalone-dash rule skips
wide East Asian letters. Everything else is zero.

Only the previous two token strings are kept, resetting at document changes.
This captures the broad pattern, not the remaining word-specific variation.
"""
import math
import unicodedata

READS = ()
DASHES = '-‐‑–—−'
PREFIXES = set(
    'non anti pre post semi multi inter intra pseudo quasi cross'.split()
)
MODIFIERS = set(
    'self real high low long short full well half double hard soft'.split()
)
NUMBER_WORDS = set('one two three four five six seven eight nine ten'.split())
LINKING_WORDS = set('to of the by'.split())
DASH_DISCOUNT = {
    '‐': 0.89, '‑': 0.89, '–': 0.33, '—': 0.81, '−': 0.74,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = carry[1:] if carry and carry[0] == doc else ('', '')
    s = prefix.token_strings[-1]
    value = 0.0
    tail = s.lstrip(DASHES)
    if s and tail != s and tail and tail[0].isalpha():
        value = 1.34 - 0.04 * min(len(tail), 12)
        if previous.startswith(' '):
            value -= 0.09
        word = previous.strip().lower()
        if word in PREFIXES:
            value -= 0.52
        elif word in MODIFIERS:
            value -= 0.49
        elif word in NUMBER_WORDS:
            value -= 0.23
        if any(c in DASHES for c in previous):
            value -= 0.35
            if previous.lstrip(DASHES) in LINKING_WORDS:
                value -= 0.32
        if (tail == 'old'
                and previous.lstrip(DASHES) in {'year', 'years', 'month'}):
            value = 0.0
        if s[0] == '—':
            value *= 0.25
        if not previous:
            value *= 0.45
    elif previous and previous[-1] in DASHES and s:
        if s[0].isalpha():
            value = 1.4 + 0.28 * previous.startswith(' ')
            value -= 0.69 * previous.endswith('--')
            if previous[-1] in '‐‑–—−':
                value -= DASH_DISCOUNT[previous[-1]]
            if '\u0400' <= s[0] <= '\u052f':
                value += 0.19
            if before.strip().lower() in PREFIXES:
                value -= 0.39
            if unicodedata.east_asian_width(s[0]) in {'W', 'F'}:
                value = 0.0
        elif s.isascii() and s.isdigit():
            n = int(s[0])
            value = -0.68 / math.sqrt(n) + 0.1 if n else -0.15
            value += 0.08 * before.isdigit()
            value -= 0.09 * previous.startswith(' ')
        elif s.isspace():
            value = -0.65 if s.isascii() else 0.0
            if previous[-1] != '-':
                value *= 0.65
        elif s.startswith(' '):
            stripped = s.lstrip()
            value = 0.08 - 0.2 * stripped[0].isupper()
            if stripped.startswith('**'):
                value = -2.3
            elif stripped.startswith('##'):
                value = -1.8
            elif stripped.startswith('['):
                value = -0.9
            elif stripped.startswith('`'):
                value = -1.5
            elif not stripped[0].isalnum():
                value = -0.35
    elif previous.strip() == '•' and s.lstrip().startswith('##'):
        value = -1.4
    elif previous and previous[0] in DASHES and s and s[0].isalpha():
        letters = previous.lstrip(DASHES)
        if letters.isalpha():
            value = 0.18 + 0.08 * max(0, 4 - len(letters))
            value += 0.09 * (len(letters) == 1)
    elif before and before[-1] in DASHES and previous.isspace() and s.isdigit():
        n = int(s[0]) if s.isascii() else 0
        value = -0.32 - 0.3 / math.sqrt(n) if n else -0.35
    return (doc, s, previous), float(value)

"""Lexical minimizers (mere, merely, just, only) give negative activations.

The strongest response is to 'merely'. Other languages' ways of saying
'only/just' also respond. The spelling 'mer' and the merge word family
trigger false positives, including in names and programming identifiers.
Split spellings such as mer + ely have a response on the ending too.
This predicts those lexical responses, not general sentence meaning.
"""
READS = ()

# English words that restrict an assertion or downplay its extent.
MINIMIZERS = {
    'merely': -4.25, 'mere': -3.25, 'just': -1.05,
    'only': -0.62, 'simply': -1.17, 'purely': -1.5,
    'solely': -0.96, 'barely': -0.99, 'mildly': -0.72,
    'plainly': -0.71, 'nearly': -0.33,
}

# Translations of 'only', 'just', and 'simply'; not arbitrary token IDs.
TRANSLATIONS = {
    '只是': -2.2, '仅仅': -2.0, '仅': -1.7, '僅': -1.6,
    '只不过': -0.95, '只不过是': -1.35,
    '只': -0.47, '只有': -0.36, '只能': -0.34,
    '只要': -0.35, '只需要': -0.59, '只需': -1.03,
    '仅为': -1.95, '只剩': -0.84, '只为': -0.65,
    'しか': -0.70, 'のみ': -1.03, 'ただ': -0.69,
