"""layers.0.mlp.down_proj:1931 -- a "merely / just / only" detector.

Fires negatively on words that mean "nothing more than": the English restrictive
adverbs merely, mere, just, simply, purely, solely, barely, only, and their
counterparts in Chinese (只是, 仅, 僅, 仅仅), Russian (просто, лишь) and Japanese
(のみ). It is strongest on "mer"-stem tokens (merely, mere, Mer, mer) and weaker
on the merge/merit family, which share the same letters. Everything else is 0.

The activation is a per-token lookup with no context: each listed word gives
nearly the same value wherever it appears (std about 0.1-0.3 within a word).
"""

READS = ()

# Typical activation for each group, from ~6000 training rows.
MERELY = -4.3
MERE = -3.0
MER = -2.2
MERGE_FAMILY = -1.6
RESTRICTIVE = -1.0
ONLY = -0.6

RESTRICTIVE_WORDS = {
    "just", "simply", "purely", "solely", "barely",
    "只是", "仅", "仅仅", "僅", "лишь", "просто", "のみ",
}
MERGE_WORDS = {"merit", "merits", "merg", "merger", "merging"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip().lower()
    if s == "merely":
        v = MERELY
    elif s == "mere":
        v = MERE
    elif s == "mer":
        v = MER
    elif "merge" in s or s in MERGE_WORDS:
        v = MERGE_FAMILY
    elif s in RESTRICTIVE_WORDS:
        v = RESTRICTIVE
    elif s == "only":
        v = ONLY
    else:
        v = 0.0
    return carry, float(v)

