        value = 1.65 if s == 's' else 0.75
    if prev in {'tow', 'to'} and s in {'ard', 'ards', 'ward', 'wards'}:
        value = 1.8
    if prev.startswith('направ') and s.startswith('лен'):
        value = 1.7
    return (document, token), float(value)

