"""Approximate the component with direction and orientation word cues.
Explicit direction words get the largest values; movement and destination
markers in several languages get smaller ones. 'Of' after a direction or
orientation word is also scored. A small shrinkage keeps these lexical guesses
from being overstated; all other tokens receive zero.
"""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].casefold()
    core = word.strip(" \t\n.,:;!?()[]{}\"'")
    doc = prefix.document_ids[-1]
    previous = ""
    if carry is not None and carry[0] == doc:
        previous = carry[1]

    value = 0.0
    if "方向" in word:
        value = 4.4
    elif "向" in word:
        value = 8.8
    elif "directional" in word:
        value = 1.3
    elif "direction" in word:
        value = 3.3
    elif "direction" in previous and core == "of":
        value = 1.2
    elif "orientation" in word:
        value = 2.1
    elif "orientation" in previous and core == "of":
        value = 0.6
    elif "toward" in word or "towards" in word:
        value = 1.9
    elif "hacia" in word or "dirección" in word:
        value = 1.8 if "hacia" in word else 1.2
    elif "направ" in word:
        value = 1.8
    elif "направ" in previous and "ления" in word:
        value = 1.8
    elif "redirect" in word:
        value = 1.65
    elif "directed" in word:
        value = 1.25
    elif "clockwise" in word:
        value = 0.8
    elif core in {"へ", "への"}:
        value = 1.1 if core == "へ" else 1.6
    elif any(term in word for term in ("upward", "downward", "sideways")):
        value = 1.0
    elif any(term in word for term in ("opposite", "reverse", "backward")):
        value = 0.35
    elif "forward" in word:
        value = 0.3
    elif "tendency" in word or "inclination" in word:
        value = 1.1
    elif "bias" in word:
        value = 0.7
    elif "trend" in word:
        value = 0.3
    elif "朝" in word or "往" in word:
        value = 2.0
    elif "赴" in word or "靠近" in word or "沿着" in word:
        value = 0.8
    elif "方" in word or core in {"从", "由", "对", "對", "比"}:
        value = 0.7
    elif "향" in word or "phía" in word or "kepada" in word:
        value = 1.2
    elif "dirig" in word:
        value = 0.65

    return (doc, word), float(0.88 * value)

programs.sol:
"""Graph/ography spellings, with weaker scientific suffix and 'however' signals.

This is a spelling-based approximation: graph-related words do not all receive
one semantic label. Separately tokenized Greek endings respond especially
strongly. A recognized stem can carry into an inflection or the following 'of'.
Other tokens receive zero; their small, mixed background is not modeled.
State resets at document boundaries.
"""
import re
import unicodedata

READS = ()

# Forms of the Greek writing/drawing root, when split from their word's stem.
GRAPH_ENDINGS = {
    'ograph': 5.9,
    'ography': 6.8,
    'ographic': 7.0,
    'ographical': 6.8,
    'ographically': 6.0,
    'ographies': 5.6,
    'ographics': 5.2,
    'ographs': 3.1,
    'ographer': 3.7,
    'ographers': 4.8,
    'ographed': 1.55,
    'ograf': 5.9,
    'ografia': 5.0,
    'ограф': 5.9,
}


def plain(s):
    return ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                   if not unicodedata.combining(c))


def strength(token, word):
    raw = token.strip().lstrip('_./')
    s, w = plain(raw), plain(word)
    separate = token[:1].isspace()
    if s == 'however':
        return 0.67 if raw[:1].isupper() else 0.58
    if s in GRAPH_ENDINGS:
        value = GRAPH_ENDINGS[s]
        if s in ('ographer', 'ographers'):
            if w.startswith('chore'):
                return 2.3
            if w.startswith(('bi', 'ethn', 'ge')):
                return 5.3
            if w.startswith('phot'):
                return 3.0
        if s == 'ography':
            if w.startswith(('phot', 'bibli', 'chore', 'porn', 'cinemat', 'vide')):
                return 4.0
            if w.startswith(('typ', 'crypt')):
                return 2.9
            if w.startswith(('chromat', 'tom', 'top', 'echocardi')):
                return 5.2
        if s.startswith('ographic'):
            if w.startswith(('phot', 'porn', 'typ', 'inf')):
                return 4.0
            if w.startswith('autobi'):
                return 5.2
        if s == 'ograph' and w.startswith(('aut', 'mon', 'chore')):
            return 4.0
        return value
    if s in ('og', 'ogr', 'ogra'):
        return (0.15 if s == 'og' else 1.2) if separate else {
            'og': 0.78, 'ogr': 3.3, 'ogra': 4.0}[s]

    # Whole-word graph relatives: geography, life-writing, and pictures.
    if any(root in s for root in ('geograph', 'geograf', 'географ')):
        return 5.4 if raw[:1].isupper() else (6.7 if s.endswith('ic') else 6.0)
    for root, value in (('autobiograph', 1.8), ('bibliograph', 2.5),
                        ('biograph', 3.7), ('paragraph', 0.65)):
        if root in s:
            return value
    if 'demograph' in s:
        return 3.3 if s.endswith('s') else 4.2
    if s.startswith(('fotograf', 'фотограф')):
        return 2.9
    if 'photograph' in s:
        return 1.8 if s.endswith(('y', 'er', 'ers', 'ed', 's')) else 2.6
    if s == 'photo':
        return 0.6
    if s in ('graph', 'graphs'):
        if raw == 'GRAPH' and not separate:
            return 5.0
        if token.startswith(('_', '.', '/')):
            return 1.8
        return 2.15 if separate else 2.4
    if s.startswith('graphic'):
        if s.endswith('s'):
            return 0.85
        return 2.0 if not separate or s.endswith('al') else 1.05
    if s.startswith(('ogram', 'agram', 'diagram', 'histogram')):
        return 1.5
    graph_fragments = ('raph', 'raphic', 'raphy', 'igraph', 'igraphy',
                       'agraph', 'agraphy')
    if s in graph_fragments or s.endswith('graph'):
        return 1.5
    if s in ('graf', 'grafik', 'grafic'):
        return 1.15
    if 'graph' in s:
        return 0.8

    # Greek scientific combining forms and a few related geographic terms.
    if s.startswith('anatom'):
        return 2.15 if s == 'anatom' else 1.2
    if s.startswith('physiol'):
        return 2.15 if 'ical' in s else 1.65
    if 'morph' in s or s.startswith('orph'):
        return 1.85 if s.endswith('ology') else 0.9
    if s.startswith(('olog', 'iolog', 'олог')):
        if w.startswith(('morph', 'hist', 'epidemi')):
            return 2.5 if 'ical' in s else 2.0
        if w.startswith(('path', 'ophys', 'phys')):
            return 1.8
        return 1.5 if 'ical' in s else 0.9
    if s.startswith('alogy'):
        return 1.7
    if s.endswith(('ology', 'ologie', 'ological', 'ologically')):
        return 0.4 if s.startswith(('techn', 'method', 'neur')) else 0.8
    for endings, value in (
        (('otyp', 'ophys', 'oscope', 'otherapy'), 1.1),
        (('ogenesis', 'osph', 'opath', 'ophob', 'osoph'), 0.9),
        (('ogen', 'ometric'), 0.4),
        (('census', 'passport'), 1.1),
        (('landscape', 'terrain', 'latitude'), 0.85),
        (('граф', 'раф'), 1.1),
    ):
        if s.startswith(endings):
            return value
    if s == 'therapy':
        return 0.2 if separate else 1.1
    if s.endswith('scopy'):
        return 0.6
    if s.startswith('diagnos'):
        return 0.8 if s.endswith('is') else 0.4
    if '地理' in s:
        return 2.9 if len(s) > 2 else 5.1
    return {'图': 0.9, '圖': 0.9, '学': 0.2, 'ог': 0.3}.get(s, 0.0)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', 0.0)
    _, word, previous = carry
    token = prefix.token_strings[-1]
    joined = word + token if token[:1].isalpha() else token
    value = strength(token, joined)
    if value == 0.0 and previous > 0.5:
        s, last = plain(token.strip()), plain(prefix.token_strings[-2].strip())
        if s == 'of' and token[:1].isspace():
            factor = 0.2 if last.startswith(('ograph', 'ograf')) else 0.5
            value = previous * factor
        elif token.isalpha():
            factor = 0.3
            if last in ('graph', 'raph') and s in ('ing', 'ed', 's', 'y'):
                factor = 0.85
            elif last.endswith('graph') and s in ('ing', 'ed'):
                factor = 0.5
            elif last == 'anatom' and s in ('ical', 'ically'):
                factor = 0.9
            elif last.startswith('фотограф'):
                factor = 0.5
            value = factor * previous
    match = re.search(r'[^\W\d_]+$', joined)
    word = match.group()[-40:] if match else ''
    return (document, word, value), float(value)

