"""Approximate the sparse response with word-shape cues.

Graph/ology fragments and several technical-looking stems recur in high-response
examples; ``however`` is a separate contrast-word cue. Other tokens return zero.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()

    if "graph" in word or "ogra" in word:
        return None, 1.6

    if "olog" in word:
