programs.sol:
"""Sentence and line boundaries, rather than arbitrary words.

Ordinary text is nearly silent. Newlines and sentence stops are positive;
short, densely broken lines, code, numbers, and abbreviations weaken them.
Han/Kana text strengthens line endings. Coefficients are fitted to training
activations; word-specific variation is omitted. The last 160 characters
provide bounded context, reset at every document boundary.
"""
import re

READS = ()
TITLES = set('mr mrs ms dr prof sr jr st'.split())
ABBREVIATIONS = set(
    'fig eq no vol pp p v vs cf inc ltd co al approx min max esp '
    'op cit ref sec dept univ e g i'.split()
)
PUNCTUATION = set('.!?。！？;；:："\'’”)]}([{,/\\`*#>- ')
WORD_END = re.compile(r'(\w+)$')


def has(text, characters):
    return any(c in text for c in characters)


def boundary_value(token, tail):
    s = token.strip()
    if '\n' not in token and not (s and set(s) <= PUNCTUATION):
        return 0.005
    line = tail.rsplit('\n', 1)[-1]
    previous = tail.rstrip()
    unquoted = previous.rstrip('"\'”’」』）)]}')
    match = WORD_END.search(previous)
    word = match.group(1) if match else ''
    code = has(line, '=[]{}/_')
    if '\n' in token:
        body = token.strip()
        paragraph = token.count('\n') > 1
        density = min(tail.count('\n'), 8) / 8
        value = 1.4
        if has(body, '.!?。！？'):
            value = 1.85 if body.count('.') > 1 else 2.25
        elif has(body, ':：'):
            value = 1.6
        elif has(body, ';；'):
            value = 1.45 + 0.5 * has(body, '"\'') + 0.3 * has(body, ')]')
        elif has(body, '{})]'):
            value = 1.65
        elif ',' in body:
            value = 1.55
        elif '/' in body or '\t' in token:
            value = 1.15
        elif not body:
            value = 1.27 + 0.83 * min(sum(c.isalnum() for c in line), 80) / 80
            value += 0.27 * bool(unquoted and unquoted[-1] in '.!?。！？')
            value -= 0.25 * (not line.strip())
            value -= 0.3 * token.startswith(' ')
            if previous.endswith(('assistant', 'user', '<tool_call>', '<tool_response>')):
                value -= 0.36
        value -= (0.6 if not body else 0.8) * density
        value += 0.1 * paragraph - 0.2 * (paragraph and '.' in body)
        cjk = sum('\u3400' <= c <= '\u9fff' or '\u3040' <= c <= '\u30ff'
                  for c in line) / max(len(line), 1)
        value += 0.68 * cjk + 0.29 * has(body, '：；，（）')
        value += 0.44 * bool(unquoted and unquoted[-1] in '。！？')
        return value - 0.8 * (not tail)
    if '。' in s:
        return 1.23
    if has(s, '?？!！'):
        return (0.85 if has(s, '?？') else 0.55) - 0.21 * code
    if '.' in s:
        if s.count('.') > 1:
            return 0.24
        if len(s) > 1:
            return 0.65 if has(s, ')]}"\'”') else 0.2
        if token.startswith(' '):
            return 0.19
        if word.isdigit() or len(word) == 1 or word.lower() in ABBREVIATIONS:
            return 0.08
        if word.lower() in TITLES:
            return -0.11
        value = 0.71 + 0.41 * min(len(word), 12) / 12
        value -= 0.36 * code + 0.29 * word.isupper()
        value -= 0.87 * bool(tail and tail[-1].isspace())
        value -= 0.59 * bool(match and match.start() > 0
                             and previous[match.start() - 1] == '.')
        return value - 0.19 * (not word)
    if has(s, ';；'):
        return 0.58
    if has(s, ':：'):
        return 0.1
    if set(s) == {'#'}:
        return 0.11 + 0.37 * (min(len(s), 3) - 1)
    return 0.005


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = boundary_value(token, tail)
    return (doc, (tail + token)[-160:]), float(value)

