programs.sol:
"""Recognize a mixture of word families and short spelling fragments.

Before/after and each/such give moderate positive responses. Teach/teacher,
coach and cache forms, and short 'ach' fragments, give stronger responses.
Several translations and accented/Cyrillic fragments give weaker responses.
Longer words merely containing 'ach' are mostly left inactive. This is a
lexical approximation, not one shared meaning or a full vocabulary table;
it deliberately ignores finer token-specific and contextual variation.
"""
import unicodedata

READS = ()


def token_activation(token):
    word = token.strip().lstrip('._-/(@').lower()
    if word in {'before', 'after', 'each', 'such'}:
        value = 1.3 if word == 'each' else 1.16
    elif (word in {'teacher', 'teachers'}
          or word in {'cache', 'cached', 'caches'}):
        value = 3.5
    elif word.startswith(('teach', 'coach', 'cach')):
        value = 2.0
        if word in {'coach', 'coaches', 'cach', 'caching'}:
            value = 2.8
    elif word.endswith('cache'):
        value = 2.0
    elif word == 'taught':
        value = 1.25
    elif word == 'ach':
        value = 2.2 if token[0].isspace() else 3.7
    elif word.startswith('ach') and len(word) <= 6:
        if word.startswith(('achie', 'achine')) or word == 'achsen':
            value = 0.4
        elif word.endswith(('er', 'ers', 'ed')):
            value = 3.7 if word.endswith('er') else 3.0
        elif word.endswith(('ing', 'es', 'en')):
            value = 1.9
        else:
            value = 2.5
    elif word == 'nach':
        value = 2.45
    elif len(word) == 4 and word.endswith('ach'):
        value = 3.0
    elif word in {'machen', 'macht'}:
        value = 1.7
    elif word in {'beach', 'peach'}:
        value = 1.2
    # Chinese teacher/coach nouns and teaching words, in both scripts.
    elif word in {'教师', '教師', '教练', '教練'}:
        value = 2.8
    elif word in {'老师', '老師', '教学', '教學'}:
        value = 1.5
    elif word in {'教', '师', '師'}:
        value = 0.9
    # Short Cyrillic spelling fragments: 'akh' and 'ach'.
    elif word in {'ах', 'ач'}:
        value = 1.0
    # Additional translations of each and after.
    elif word in {'cada', 'chaque', '各'}:
        value = 1.0
    elif word in {'每个', '每個', '各个', 'после', 'après'}:
        value = 0.6
    else:
        unaccented = ''.join(
            c for c in unicodedata.normalize('NFD', word)
            if not unicodedata.combining(c)
        )
        if word != unaccented and 'ach' in unaccented and len(word) <= 6:
            value = 1.5 if unaccented.startswith('ach') else 0.8
        else:
            value = 0.0
    return value


def step(carry, prefix, upstream):
    return None, float(token_activation(prefix.token_strings[-1]))

