programs.sol:
"""Detect list-marker punctuation, checks, and nonbreaking spaces.

A round bullet has the largest negative response, strongest near the start
of a document. Hyphens, stars and numeric/letter label endings respond at
line starts; ordinary punctuation is almost inactive. Markdown emphasis
immediately after a list label also responds. Only a short line tail is
retained; state resets per document.
"""
import math
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, origin, position = '', 'document', 0
    else:
        line, origin, position = carry[1:]
        position += 1
    token = prefix.token_strings[-1]
    mark = token.strip()
    start = not line.strip()
    value = 0.0
    if mark == '•':
        value = -3.75 - 3.75 / math.sqrt(position + 1)
        value += 0.85 * token.startswith(' ') - 0.6 * (not start)
    elif mark == '●':
        value = -3.0 + 0.6 * token.startswith(' ')
    elif token == '\u00a0':
        value = -0.6
    elif mark in {'✓', '✔'}:
        value = -0.9 if token.startswith(' ') else -0.75
    elif mark in {'-', '*', '–'} and start:
        value = -1.3 if mark == '-' else -0.45
        if token.startswith(' '):
            value = -0.78 if mark == '-' else -0.07
        if origin == 'escape' and token == '-':
            value = -0.43
    elif mark in {'.', ')', '、'}:
        label = re.sub(r'^\s*[>#*"“]+\s*', '', line).strip()
        if re.fullmatch(r'\d{1,4}|[a-zA-Z]', label):
            if label.isdigit():
                value = -0.53 if len(label) == 1 else -0.4
                if len(label) > 2:
                    value = -0.16
            else:
                value = -0.74 if mark == ')' else -0.53
                if label.lower() not in 'abcde':
                    value *= 0.55
            if origin != 'newline':
                value *= 0.25
    elif mark == '**':
        value = -0.37 if token.startswith(' ') else -0.07
        label = re.sub(r'^\s*[>#]+\s*', '', line)
        if re.fullmatch(r'\s*(?:[-*]|\d+[.)])\s*', label):
            value = -0.66
    line += token
    if '\n' in token:
        origin = 'newline'
    elif '\\n' in line:
        origin = 'escape'
    line = line.replace('\\n', '\n').split('\n')[-1][-100:]
    return (doc, line, origin, position), value

