"""Approximate the negative activation on bullets and list-like punctuation."""
import re

READS = ()

BULLETS = frozenset("•●◦▪▫■□◆◇")
CHECKS = frozenset("✓✔☑")
DASHES = frozenset("-‐‑‒–—")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    line = "" if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    mark = token.strip()
    value = 0.0

    if mark in BULLETS:
        value = -4.0
    elif mark in CHECKS:
        value = -0.8
    elif mark in DASHES and not line.strip():
        value = -1.25
    elif mark in {".", "．"} and re.fullmatch(r"\s*\d{1,3}", line):
        value = -0.55
    elif mark == "、" and re.search(r"\d\s*$", line):
        value = -0.65
    elif mark == ")" and re.fullmatch(r"\s*[A-Za-z0-9]", line):
        value = -0.55
    elif mark == "*" and not line.strip():
        value = -0.45
    elif "\u00a0" in token:
        value = -0.4

    joined = line + token
    if "\n" in joined:
        line = joined.rsplit("\n", 1)[-1]
    else:
        line = joined[-160:]
    return (doc, line), float(value)

programs.sol:
"""A surface-syntax approximation to a quotation-boundary detector.

Triple quotation marks dominate, including a third quote following a
paired-quote token; document-initial triples are strongest. Smaller
responses mark backtick fences, escaped quotes, block comments, display
math, string-formatting cues and documentation markers. Ordinary quotes
are adjusted for adjacent whitespace and programming punctuation.
'Following' has a negative response, especially after 'which of the'.

Response levels were estimated from training examples. This is not a
parser: it keeps only the previous token, document position, and a short
text suffix, and uses a near-zero baseline for everything else.
"""
import re

READS = ()


def boundary(s, prev, position, recent):
    for q in ('"', "'"):
        if q * 3 in s:
            head = s.split(q * 3)[0]
            if position == 0:
                return 8.3 if q == '"' else 6.45
            if position < 16:
                return 5.0 if q == '"' else 4.5
            if '\n\n' in s:
                return 3.6 if head else 3.0
            if '\n' in s:
                return 3.95
            if not head:
                return 5.15 if q == '"' else 4.3
            if q == "'" and (prev.isspace() or prev.endswith('\n')):
                return 4.1
            return 4.25 if q == '"' else 3.0
        if s.startswith(q) and prev.endswith(q):
            n = len(prev) - len(prev.rstrip(q))
            run = n + len(s) - len(s.lstrip(q))
            if n < 3:
                if run >= 3:
                    return 3.7 if q == '"' else 4.45
                return 0.18 if q == '"' else 0.49
        if q * 2 in s:
            head = s.split(q * 2)[0]
            if not head:
                return 1.05 if q == '"' and s == q * 2 else 0.60
            return 0.05 if head.isspace() else 0.14
    for q in ('"', "'"):
        escaped = '\\' + q
        if s.startswith(escaped) and prev.endswith(escaped):
            return 0.60 if s.endswith('\\') else 0.38
    stripped = s.strip()
    if '```' in s:
        return 1.4 if prev.endswith('``') else 1.3 if position == 0 else 0.72
    if s.startswith('`') and prev.endswith('`'):
        if '\\' in s:
            return 1.54
        if s.startswith('``'):
            return 0.68 if prev.endswith('``') else 1.23
        return 0.38 if '\n\n' in s else 0.75
    if s.startswith('(`'):
        return 0.33
    if stripped.startswith('/*'):
        return 0.09 if stripped.startswith('/**') else 0.63
    if stripped.startswith('*/'):
        return 0.37
    if stripped == '$$':
        return 0.19 if s.startswith(' ') else 0.05
    if stripped == 'EOF':
        return 0.58
    if stripped == 'Args':
        return 0.32
    if s in ('format', '.format', ' format'):
        return 0.38 if s == 'format' else 0.14 if s == '.format' else 0.08
    if s == 'code' and prev.endswith(('<', '</')):
        return 0.17
    if s == ' following':
        return -1.09 if recent.lower().endswith('which of the') else -0.26
    if '"' in s or "'" in s:
        if re.search(r'(?:^|[\s(=])f$', prev, re.I) and s.startswith(('"', "'")):
            return 0.63
        if s in ('"', "'"):
            single = s == "'"
            if position == 0:
                return 0.89 if single else 0.56
            if prev.isspace():
                if '\n' in prev:
                    return 0.29 if single else 0.14
                return 0.21
            if prev.endswith((')', ']', '}', '\n')):
                return 0.25
            if prev and prev[-1].isalnum():
                return 0.0 if single else -0.07
            return 0.30 if single else 0.15
        if s in (' "', " '"):
            single = s.endswith("'")
            if prev.endswith(('<<', '>>')):
                return 0.52 if single else 0.36
            if prev.isspace():
                return 0.10 if single else 0.07
            if prev and prev[-1].isalnum():
                return 0.10 if single else 0.02
            if prev.endswith((',', ':', ';')):
                return -0.04
            return 0.10 if single else 0.02
        if s.startswith("('"):
            return 0.18
        if s.startswith(('"', "'")) and (')' in s or ']' in s):
            return 0.08
    if s == ' `':
        return -0.18 if prev.endswith('`') else 0.10
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        prev, position, recent = '', 0, ''
    else:
        _, prev, position, recent = carry
    value = boundary(s, prev, position, recent)
    return (doc, s, position + 1, (recent + s)[-80:]), float(value)

programs.luna:
"""Mark string and code boundaries, with a cue for “the following” phrases."""

READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1].strip()

    # Three matching quotes commonly open or close a multiline string.
    if '"""' in text:
        return None, 4.0
    if "'''" in text:
        return None, 3.4

    # Backtick fences and block-comment brackets mark code boundaries.
    if text and set(text) == {"`"}:
        return None, 0.8 if len(text) >= 3 else 0.2
    if text in {"/*", "*/"}:
        return None, 0.5
    if text == "EOF":
        return None, 0.6

    # A list introduced by “the following” tends to have a negative response.
    if text.lower() == "following" and prefix.position > 0:
        same_doc = prefix.document_ids[-2] == prefix.document_ids[-1]
        previous = prefix.token_strings[-2].strip().lower()
        if same_doc and previous == "the":
            return None, -0.45

    if text in {'"', "'", "‘", "’", "“", "”"}:
        return None, 0.2
    if text in {"$$", "$"}:
        return None, 0.3
    return None, 0.0

programs.sol:
"""Approximate a negative response to opening string/quotation delimiters.

A space followed by a quote is most negative after another quoted field,
assignment, or a preceding whitespace token. In prose after articles and
speech verbs, the prediction is weak or positive. Fused and escaped
delimiters have their own
strengths; bare quotes and object/list openers are usually positive.
Only a previous token and a short text suffix are remembered, reset
at document boundaries. Small ordinary-word responses are not modeled.
"""
READS = ()
ARTICLES_AND_POSSESSIVES = set(
    'the a an my your his her its our their'.split()
)
SPEECH = set(
    'say says said saying call calls called named titled '
    'wrote writes asked asks'.split()
)
OUTPUT = set('print println printf write writeln writeline log echo'.split())


def opening(previous, tail, single):
    p = previous.strip()
    if not previous:
        return -1.18 if single else -0.74
    if not p:
        if tail.endswith(',') and any(q in tail for q in '\"\''):
            return -2.3
        return -1.6 if single else -1.4
    if p[-1] in ':,' and any(q in p for q in '\"\'”’'):
        return -2.8 if single else -2.15
    if p.endswith('='):
        return -2.0 if single else -1.75
    if p.endswith(('=>', '->')):
        return -2.6 if single else -2.1
    if p.endswith(':'):
        return -1.85 if single else -1.1
    if p.endswith(','):
        return -1.3 if single else -0.7
    if p.endswith(('+', '|', '&', '?')):
        return -1.1 if single else -0.8
    if p.endswith(('(', '[', '{')):
        return -1.25 if single else -0.9
    if p.endswith(('"', "'", '”')):
        return -1.25 if len(p) == 1 else -0.6
    word = p.lower()
    if word in ARTICLES_AND_POSSESSIVES:
        return 0.25
    if word in SPEECH:
        return 0.1
    if word in {'and', 'or', 'nor'}:
        return -0.8
    if word in {'return', 'yield', 'case', 'comment', 'values', 'default'}:
        return -1.5
    if word == 'from':
        return -1.0 if single else -0.4
    if word in {'to', 'as', 'is', 'was', 'were', 'are', 'be'}:
        return -0.5 if single else -0.2
    return -0.3 if single else -0.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        previous, tail = carry[1:]
    s = prefix.token_strings[-1]
    value = -0.003
    if s in (' "', " '"):
        value = opening(previous, tail, s == " '")
    elif s.startswith((' "', " '")):
        rest = s[2:]
        if all(c in '\"\';,:\n\r ' for c in rest):
            value = -0.1
        elif all(c in ');]} ' for c in rest):
            value = -0.3
        else:
            value = 0.5 * opening(previous, tail, s[1] == "'") - 0.25
    elif s == ' \\"':
        value = -2.2 if previous.strip().endswith(('=', ':', ',')) else -1.6
    elif s in (' “', ' ‘'):
        value = 0.45 * opening(previous, tail, False) - 0.02
    elif s in ('("', "('"):
        name = previous.strip().lstrip('.').lower()
        value = -0.08 if name in OUTPUT else -0.6
    elif s.startswith('(\\"'):
        value = -1.1
    elif s in ('="', "='", '=\\"'):
        value = -1.2 if s == '="' else -1.6
    elif s in ('","', "','"):
        value = -1.35
    elif s in ('":"', "':'"):
        value = -2.25
    elif s in (':"', ":'"):
        value = -1.0
    elif s == '\\"':
        value = -0.72
    elif s.startswith('\\"'):
        value = -0.27
    elif s in ('"', "'", '“'):
        value = 0.1
    elif s in ('{"', ' {"', '["', "['"):
        value = 0.68 if s == '{"' else 0.25
    return (doc, s, (tail + s).rstrip()[-8:]), float(value)

"""A mostly negative WHO/WH/WHEEL spelling response.

The strongest triggers are wheel and the Chinese wheel characters 轮/輪.
Who, whom, whose, and short wh fragments also trigger it. Human referents
weaken who; commas and identifying verbs strengthen it. Split wh words
can retain a weaker response on their next piece. Other tokens are zero,
except listed non-English who forms and Arabic dhal fragments. State is
only the previous token, and resets at each document boundary.
"""
READS = ()

HUMAN_NOUNS = frozenset("""
man men woman women girl boy child children kid kids guy guys
student students patient patients player players user users
worker workers employee employees customer customers teacher teachers
engineer engineers participant participants farmer farmers
""".split())
HUMAN_REFERENTS = frozenset(
    'those person someone anyone everyone individuals'.split()
)
LINKS = frozenset('and but or of for about on'.split())
IDENTIFYING_VERBS = frozenset('know knows knew guess see ask asked'.split())


def spelling(token):
    return token.strip().strip('._-').lower()


def response(token, word):
    if word == 'wh':
        return -1.4 if token.strip() == 'WH' else -3.02
    if word == 'whe':
        return -2.87
    if word in ('whit', 'whisk'):
        return -2.1
    if word == 'whom':
        return -2.89
    if word == 'who':
        return -0.735 if token == ' who' else -1.07
    if word == 'whose':
        return -1.11
    if word in ('wheel', 'wheels'):
        return -4.02
    if word.startswith('wheel') or word in ('whistle', 'whirl', 'whims'):
        return -1.4
    if word in ('轮', '輪'):
        return -7.1
    # Round-count expressions are stronger than ordinary wheel compounds.
    if word in ('一轮', '一輪'):
        return -5.9
    if word in ('首轮', '首輪'):
        return -4.1
    if word.endswith(('一轮', '一輪')):
        return -3.2
    if '轮' in word or '輪' in word:
        return -1.2
    if word in ('ذ', 'الذ', 'الذين'):
        return -1.6
    if word in ('谁', '誰', 'quien', 'quem'):
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    word, prior = spelling(token), spelling(previous)
    value = response(token, word)
    if token == ' who':
        if prior == 'people':
            value = -0.36
        elif prior in HUMAN_REFERENTS:
            value = -0.47
        elif prior in HUMAN_NOUNS:
            value = -0.56
        elif prior in IDENTIFYING_VERBS:
            value = -1.16
        elif previous.rstrip().endswith(',') or prior in LINKS:
            value = -0.97
    elif token == ' whose':
        value = -1.21 if previous.rstrip().endswith(',') else -1.05
    if token.isascii() and token.isalpha():
        echo = {'wh': -1.0, 'whe': -0.65, 'whisk': -1.5, 'whit': -0.25}
        value = min(value, echo.get(prior, 0.0))
        if previous.lower().endswith('w') and word.startswith('heel'):
            value = min(value, -3.9 if word.startswith('heels') else -2.7)
    if token == ' of' and prior in ('wheel', 'wheels'):
        value = -2.0
    return (doc, token), float(value)

