programs.sol:
"""A local spelling-boundary heuristic for the character l.

Looks at the previous token's last character and the current one's first.
Latin a/e/o/u have positive base weights; i/j/y/l have negative ones.
Short neighboring fragments strengthen vowel responses. Consonant
clusters, the second letter and case make small adjustments. Fixed rules
cover other Latin initials, apostrophes, and l in Cyrillic, Greek and
Arabic. Unlisted boundaries return zero. Document changes clear the
previous token.
"""
import unicodedata

READS = ()
OTHER_LATIN = {
    'j': -0.97, 'l': -0.36, 'y': -0.45, 'b': 0.36,
    'r': 0.34, 's': 0.20, "'": 0.51, '’': 0.78,
}
CYRILLIC = {
    'а': 1.45, 'е': 0.29, 'и': -0.66, 'і': -1.05,
    'о': 1.02, 'у': 0.74, 'ы': 0.48, 'л': -0.4,
}
GREEK = {'α': 0.4, 'ε': 0.39, 'ι': -0.54, 'ο': 0.44}
ARABIC = {'ا': 1.10, 'ي': -0.7, 'ی': -0.7, 'ه': 0.5}


VOWEL_WEIGHTS = {'a': 1.89, 'e': 0.84, 'i': -0.74, 'o': 1.32, 'u': 0.82}


def latin_vowel(previous, token):
    word = ''.join(c for c in unicodedata.normalize('NFD', token.lower())
                   if not unicodedata.combining(c))
    prior = previous.lower().strip()
    strength = 1.0 - 0.10 * (min(8, len(prior)) - 2)
    strength -= 0.15 * (min(8, len(word)) - 2)
    value = VOWEL_WEIGHTS[word[0]] * max(0.1, strength)
    if prior.endswith('ll'):
        value -= 0.15
    elif len(prior) > 1 and prior[-2] in 'bcdfgkpstv':
        value -= 0.28
    if len(word) > 1 and word[1] in 'mnlr':
        value += 0.27
    if token[0].isupper():
        value -= 0.10
    return value


def base(character):
    return unicodedata.normalize('NFD', character.lower())[:1]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    value = 0.0
    if previous and token:
        end, start = base(previous[-1]), base(token[0])
        if end in ('l', 'ł'):
            value = (latin_vowel(previous, token) if start in VOWEL_WEIGHTS
                     else OTHER_LATIN.get(start, 0.0))
        elif end == 'л':
            value = CYRILLIC.get(start, 0.0)
        elif end == 'λ':
            value = GREEK.get(start, 0.0)
        elif end == 'ل':
            value = ARABIC.get(start, 0.0)
    return (doc, token), value

