programs.haiku:
"""Layer-0 MLP down-projection component 1953: a word right after "the".

Its activation is near zero for most tokens. It switches on for the word that
directly follows "the" (the previous token must be "the"), and its sign and size
depend on the kind of word:
  * time-period nouns (day, time, way, end, moment, night, year, future ...) and
    degree/kind words (more, kind, type, fact, amount, actual ...): about +1.1;
  * "the very": about +3.4 (the largest response); "very" elsewhere: +0.3;
  * part/location nouns (line, point, side, part, region, level, stage ...): +0.6;
  * people and role nouns (people, children, owners, user, author, president ...)
    and back-reference words (above, former, specified, other ...): about -0.8;
  * "speaker" anywhere (as in "The speaker ..."): about -1.2;
  * a capital "The" right after <|endoftext|>, opening a document: about +1.0.
Everything else is 0. Plain-word lists stand in for the concepts; the numbers are
rough group means read off the activations.
"""

READS: tuple[str, ...] = ()

TIME_PERIOD = set(
    "day days moment hour night time year years future week weeks month morning evening "
    "date season period end stage weekend way".split()
)
DEGREE_KIND = set(
    "more kind type fact amount extent degree bit exact particular real specific actual like".split()
)
PEOPLE_ROLES = set(
    "speaker author authors writer owner owners user users participants people children men "
    "women president king queen mayor director students soldiers emperor fans residents girls "
    "mothers patients defendant defendants reader voter".split()
)
PART_NOUNS = set("line point side part region level stage number role field area place".split())
BACK_REFERENCE = set("above former aforementioned specified foregoing other".split())


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word == "speaker":
        return carry, -1.2
    if word == "the" and prev == "<|endoftext|>":
        return carry, 1.0
    if word == "very":
        return carry, 3.4 if prev == "the" else 0.3
    if prev != "the":
        return carry, 0.0
    if word in TIME_PERIOD or word in DEGREE_KIND:
        return carry, 1.1
    if word in PART_NOUNS:
        return carry, 0.6
    if word in PEOPLE_ROLES:
        return carry, -0.8
    if word in BACK_REFERENCE:
        return carry, -0.8
    return carry, 0.0

