programs.haiku:
"""Adverbs and chat-markup tags (layer-0 MLP output, component 1956).

Reads only the current token (plus the one before it, for the start of a document).
It is high on manner, degree and frequency adverbs, nearly all the -ly ones
("quickly", "highly", "carefully") and "really", "always", "already", "usually";
high on the tool-call markers <tool_call>, </tool_call>, <tool_response>,
</tool_response>; high on <|im_start|> when it opens a document after <|endoftext|>;
and moderately high on the Chinese copula 是. It is near zero for other words,
including words that only look like adverbs ("only", "family", "early", "apply",
"poly") and sentence-opening connectives ("however", "accordingly", "finally").
"""

READS = ()

NOT_ADVERB_LY = {"only", "family", "early", "apply", "supply", "reply", "rely", "imply",
                 "comply", "multiply", "july", "italy", "belly", "lonely", "ugly", "holy",
                 "likely", "unlikely", "friendly", "butterfly", "deadly", "lovely",
                 "costly", "jelly", "assembly", "anomaly", "timely", "lively", "rally",
                 "poly", "fly", "oly", "daily"}
CONNECTIVES = {"accordingly", "additionally", "alternatively", "finally", "similarly",
               "respectively", "unfortunately", "moreover", "furthermore", "likewise",
               "however", "therefore", "otherwise", "exactly", "approximately"}
ADVERBS = {"always", "already", "really", "actually", "usually", "especially",
           "particularly", "typically", "basically", "totally", "probably"}
TAGS = {"<tool_call>": 2.0, "</tool_call>": 1.5, "<tool_response>": 1.4,
        "</tool_response>": 1.5}
LY_VALUE = 1.2
ADVERB_VALUE = 0.9


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in TAGS:
        return carry, TAGS[token]
    if token == "<|im_start|>":
        after_document_end = len(prefix.token_strings) > 1 and prefix.token_strings[-2] == "<|endoftext|>"
        return carry, 1.0 if after_document_end else 0.0
    if "是" in token:
        return carry, 0.5
    word = token.strip().lower()
    if word in ADVERBS:
        return carry, ADVERB_VALUE
    if word.isalpha() and word.endswith("ly") and word not in NOT_ADVERB_LY and word not in CONNECTIVES:
        return carry, LY_VALUE
    return carry, 0.0

programs.luna:
"""Approximate the component's strong response to English -ly words and tool markers."""
import re

READS = ()

NON_ADVERBS = {
    "only", "family", "early", "likely", "July", "supply", "apply",
    "reply", "multiply", "comply", "Italy", "assembly", "friendly",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""

    # Read the last ASCII word, joining subword pieces when they continue one word.
    match = re.search(r"([A-Za-z]+)[^A-Za-z]*$", token)
    piece = match.group(1).lower() if match else ""
    is_one_word = bool(re.fullmatch(r"[A-Za-z]+[^A-Za-z]*", token))
    word = (previous if is_one_word else "") + piece
    word = word[-40:]
    if not token or not token[-1].isascii() or not token[-1].isalpha():
        next_word = ""
    else:
        next_word = word

    marker = token.strip()
    if marker == "<tool_call>":
        value = 2.0
    elif marker == "</tool_call>":
        value = 1.9
    elif marker == "</tool_response>":
        value = 1.6
    elif word.endswith("ly") and word not in {w.lower() for w in NON_ADVERBS}:
        value = 0.95
    else:
        value = 0.0
    return (doc, next_word), float(value)

programs.sol:
"""A pulse at the start of a parenthetical expression.

Common connective and explanatory words give negative pulses, while capital
initials and acronyms usually give positive ones. Most strongly this happens
immediately after a space-prefixed opening parenthesis; brackets, dashes,
ellipses, and unspaced parentheses give weaker pulses. Ordinary lowercase
fragments have a small negative response. Fragments of the explanatory
abbreviations i.e. and e.g. have their own pulses.
A few explanatory phrases and hyphen-prefixed fragments have weaker pulses.
Outside these cases the prediction is zero. History resets between documents.
The strengths are training estimates. This captures the large aside-opening
responses, not fine token-specific or longer-context variation.
"""
READS = ()

# Words linking an aside to the sentence around it.
LINKS = {
    'including': -6.6, 'and': -6.2, 'or': -5.6, 'which': -5.6,
    'though': -5.6, 'although': -5.2, 'with': -5.0,
    'such': -4.8, 'assuming': -4.9, 'that': -4.6,
    'as': -4.3, 'for': -4.3, 'of': -4.5, 'but': -4.5,
    'like': -4.2, 'also': -4.2, 'because': -4.0,
    'see': -3.9, 'since': -3.9, 'not': -3.9, 'from': -3.9,
    'except': -4.0, 'excluding': -3.8,
    'in': -3.6, 'by': -3.6, 'to': -3.6, 'if': -3.4,
    'where': -3.2, 'who': -3.6, 'when': -3.3, 'whether': -3.7,
    'without': -3.3, 'unless': -3.7, 'so': -3.2,
    'using': -3.2, 'according': -3.4, 'after': -3.2,
    'given': -2.7, 'even': -2.6, 'here': -2.6, 'at': -3.1,
    'on': -2.3, 'between': -2.0, 'about': -2.2,
    'the': -3.8, 'a': -1.0, 'an': -2.0, 'this': -1.0,
    'born': -1.4, 'use': -1.7, 'now': -2.7,
    'via': -2.5, 'through': -2.8, 'incl': -3.7,
    'например': -3.7, 'или': -3.5,
    '如': -3.1, '例如': -2.6, '包括': -4.0, '含': -4.0, '即': -2.5,
    'в': -1.7, 'с': -1.4, 'по': -3.1, 'не': -1.4, 'при': -1.7,
}
REFERENTIAL_WORDS = set('it he she we you they there each both most other more'.split())
MODALS = set('can could may might must shall should will would'.split())
QUALIFIERS = set('no non only some one all default optional'.split())
ELABORATIONS = set(
    'say either shown aka think formerly based depending again'.split()
)
STRONG_QUALIFIERS = set(
    'especially particularly sometimes possibly rather'.split()
)
QUALIFYING_ADVERBS = set(
    'usually typically often maybe instead otherwise perhaps'.split()
)
REFERENCES = {'Fig', 'Figure', 'Example', 'Table', 'FIG', 'FIGURE'}
PHRASES = {
    ('for', ' example'): -1.4,
    ('such', ' as'): -1.2,
    ('at', ' least'): -1.3,
    ('also', ' known'): -1.0,
    ('in', ' particular'): -0.8,
    ('as', ' well'): -0.4,
}


def word_value(word):
    if word in LINKS:
        return LINKS[word]
    if word in STRONG_QUALIFIERS:
        return -5.1
    if word in QUALIFYING_ADVERBS:
        return -3.8
    if word in REFERENTIAL_WORDS:
        return -2.3
    if word in MODALS:
        return -1.6
    if word in QUALIFIERS:
        return -1.8
    if word in ELABORATIONS:
        return -3.4
    if word == 'Note':
        return -1.9
    if word in REFERENCES:
        return -0.35
    if word == 'See':
        return -2.4
    if word in {'The', 'In', 'As', 'For'}:
        return -0.4
    if word.istitle() and len(word) > 1 and word.lower() in LINKS:
        return 0.35 * LINKS[word.lower()]
    if len(word) > 2 and word.isupper() and word.lower() in LINKS:
        return 0.65 * LINKS[word.lower()]
    if word.isalpha() and word.isupper():
        return 0.7 if word in {'A', 'I', 'X', 'Y'} else 1.4
    if word.isalpha() and word[0].isupper():
        return 0.6
    if word.isdigit():
        return 0.18
    if word.isalpha() and word.islower():
        if not word.isascii():
            return 0.25 if len(word) == 1 and 'α' <= word <= 'ω' else -0.25
        if word in {'i', 'ii', 'iii', 'iv', 'e'}:
            return -0.6
        if len(word) == 1:
            return -0.15
        if len(word) > 5 and word.endswith('ly') and word != 'family':
            return -3.2
        if len(word) > 4 and word.endswith(('ing', 'ed')):
            return -1.15
        return -0.7
    return 0.0


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    before_prev = carry[2] if carry is not None and carry[0] == doc else ''
    value = 0.0
    if s == '.e' and prev.strip() == 'i':
        value = -3.7 if before_prev == ' (' else -0.95
    elif s == '.g' and prev.strip() == 'e':
        value = -2.35 if prev == 'e' else -0.5
    elif (prev, s) in PHRASES:
        value = PHRASES[prev, s]
    else:
        scale = 0.0
        word = s.strip()
        if prev == ' (':
            scale = 0.2 if s.startswith(' ') else 1.0
        elif prev == '（':
            scale = 1.0 if word in {'如', '例如', '包括', '含', '即'} else 0.8
        elif prev == '[':
            scale = 0.12
        elif prev.rstrip().endswith(('(', '[')):
            scale = 0.3
        elif prev in {'...', '…'}:
            scale = 0.15
        elif prev in {' -', ' –', ' —', ' --', '--', '—', '–'}:
            scale = 0.15 if prev == ' -' else 0.22
        elif s.startswith(('(', '-')) and len(s) > 1:
            scale = 0.2 if s[0] == '(' else 0.08
            word = s[1:].strip()
        if scale:
            value = scale * (word_value(word) if word else 0.3)
    return (doc, s, prev), float(value)

"""A sparse approximation of pulses at line and message boundaries.

Newlines after the user role, page counters, headings, and code fences are
positive. These recur in high-activation training examples. Ordinary text
is near zero. Chat control markers and newline punctuation have smaller
offsets. Only two short lines are remembered,
and memory resets for each document; token-specific fluctuations are omitted.
"""
import re

READS = ()

CHAT_MARKERS = {
    '<|endoftext|>': -0.08,
    '<|im_start|>': -0.05,
    '</think>': -0.24,
}
CHAT_LINES = {
    '<|im_start|>user': 1.32,
    '<|im_start|>assistant': 0.05,
    '<tool_response>': 0.37,
    '<tool_call>': -0.10,
    '<think>': -0.08,
    '</think>': 0.40,
    '<|im_end|>': -0.02,
}
WEB_LABELS = {
    'share', 'tags', 'show tags', 'hide tags', 'comments', 'comment',
    'replies', 'reply', 'posts', 'topics', 'similar', 'more', 'register',
    'offline', 'advertisement', 'author message', 'author comment',
    'view profile', 'view details', 'related posts',
}
EDUCATION = {
    'q', 'question', 'answer', 'correct answer', 'explanation',
    'worksheet', 'math', 'lesson plan', 'math expert',
}
SECTIONS = {
    'references', 'external links', 'further reading', 'see also',
    'description', 'discussion', 'summary', 'conclusion', 'notes',
    'contents', 'abstract',
}


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        line, previous_line = '', ''
    else:
        _, line, previous_line = carry
    value = CHAT_MARKERS.get(token, 0.002)
    if token == 'assistant' and line.endswith('<|im_start|>'):
        value = -0.09
    if token.lstrip() in {'###', '####'} and not line.strip():
        value = 1.32 if re.search(r'\bviews$', previous_line.lower()) else 0.0
    if '\n' in token:
        complete = (line + token.split('\n', 1)[0]).strip()
        label = complete.lstrip('#*• ').rstrip('*:').strip().lower()
        value = 0.0
        if token in ('\n', '\n\n'):
            value = 0.04 if len(complete) < 40 else -0.01
            if len(complete) < 20:
                heading = complete.istitle() or complete.isdigit()
                value = 0.22 if heading else 0.09
            if label in SECTIONS:
                value = 0.45
            if label in WEB_LABELS or re.fullmatch(r'\d+\s*answers?', label):
                value = 0.97
            if re.search(r'\b(views|likes)$', label):
                value = 1.62
            if re.search(r'\b(member|moderator|contributor)$', label):
                value = 0.53
            profile_fields = ('joined:', 'location:', 'gender:', 'user id:')
            if label.startswith(profile_fields):
                value = 0.41
            if any(c in complete for c in '{};='):
                value = -0.04
            for suffix, pulse in CHAT_LINES.items():
                if complete.endswith(suffix):
                    value = pulse
                    break
        else:
            ending = token.rstrip('\r\n')[-1:]
            punctuation = {'?': -0.09, '!': 0.08, '>': 0.14, ']': 0.04}
            value = punctuation.get(ending, 0.0)
        if complete.startswith('```') and len(complete) < 25:
            value = 0.58
            if complete == '```':
                value = 0.28 if token.endswith('\n\n') else 0.54
        if label in EDUCATION:
            value = 0.72
        previous_line = complete[-256:]
        line = token.rsplit('\n', 1)[1][-256:]
    else:
        line = (line + token)[-256:]
    return (doc, line, previous_line), float(value)

programs.haiku:
"""Chat-turn and short-label newlines (draft 3).

The component reads a newline token, and how strongly it fires depends on the
line the newline ends. The clearest case is the newline right after the chat
role label `user` (in `<|im_start|>user`), which fires at about 1.3. Newlines that
end other one- or two-word labels (`</think>`, `<tool_response>`, `References`)
fire moderately; longer lines and the `assistant` role newline are near zero.
Special tokens sit slightly negative.
"""
READS = ()

# Newline-ended labels that the component responds to, with typical activation.
LABEL_VALUE = {"user": 1.35, "</think>": 0.4, "<tool_response>": 0.4, "References": 0.4}
NEWLINES = ("\n", "\n\n")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    line = "" if carry is None or carry[0] != doc else carry[1]
    if tok in NEWLINES:
        label = line.strip()
        if label in LABEL_VALUE:
            value = LABEL_VALUE[label]
        elif label == "assistant":
            value = 0.0
        elif 0 < len(label.split()) <= 2:
            value = 0.09
        else:
            value = 0.09 if tok == "\n\n" else 0.0
        return (doc, ""), float(value)
    if tok.startswith("<|"):
        return (doc, ""), -0.05
    return (doc, line + tok), 0.0

