"""Marks the user-message newline, with a small baseline for blank lines."""

READS = ()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    if len(tokens) < 3 or tokens[-1] not in ("\n", "\n\n"):
        return None, 0.0
    if tokens[-1] == "\n" and tokens[-2] == "user" and tokens[-3] == "<|im_start|>":
        return None, 1.35
    if tokens[-1] == "\n\n":
        return None, 0.10
    return None, 0.03

programs.sol:
"""A lexical response to guiding values, principles, and moral obligations.

Moral/core values are strongly negative; numeric values are weak.
Singular value distinguishes appreciation, commercial worth, and quantities. Recent
cultural vocabulary strengthens ambiguous 'values'. Chinese moral vocabulary
has similar lexical responses. Selected normative phrases have a short echo.
This models the salient family, not the many smaller idiosyncratic responses.
"""
READS = ()
MORAL = {'core', 'moral', 'ethical'}
PERSONAL = {'personal', 'professional', 'democratic', 'socialist', 'essential'}
CULTURAL = {'human', 'cultural', 'societal', 'social', 'family', 'religious',
            'spiritual', 'christian', 'american', 'corporate', 'company',
            'organizational', 'fundamental'}
SHARED = {'traditional', 'shared', 'common'}
CULTURE = MORAL | PERSONAL | CULTURAL | SHARED | {
    'beliefs', 'ideologies', 'traditions', 'god', 'godly', 'faith',
    'mission', 'vision',
    'ethics', 'community', 'morals', 'principles', 'norms', 'rights', 'goals',
    'leadership', 'integrity', 'honesty', 'responsibility'}
NUMERIC = {'numeric', 'numerical', 'integer', 'boolean', 'string', 'parameter',
           'maximum', 'minimum', 'null', 'nan', 'depth', 'pixel', 'sensor',
           'absolute', 'possible', 'initial', 'default', 'calculated', 'keys',
           'array', 'variable', 'variables', 'input', 'output', 'matrix',
           'hash', 'return', 'mean', 'average'}
GUIDING = {'key', 'basic', 'fundamental', 'guiding', 'important', 'central'}
CHINESE = {'道德': -0.32, '伦理': -0.22, '品德': -0.58, '理念': -0.28,
           '理想': -0.14, '理想信念': -0.60, '价值观': -0.77,
           '精神': -0.34, '价值': -0.14}


def response(token, history):
    word = token.strip().lower()
    prev = history[-1] if history else ''
    recent = set(history)
    if word == 'values':
        if token.strip().isupper():
            return -0.20  # SQL VALUES, not a moral judgment.
        if prev in MORAL:
            return -1.68
        if prev in PERSONAL:
            return -1.40
        if prev in CULTURAL:
            return -1.09
        if prev in SHARED:
            return -0.62
        if prev in NUMERIC:
            return 0.04
        if recent & CULTURE:
            return -0.72
        if recent & NUMERIC:
            return -0.04
        if prev in {'our', 'your', 'his', 'her', 'own'}:
            return -0.79
        if prev in {'their', 'its'}:
            return -0.34
        if prev == 'and':
            return -0.45
        return -0.10 if token[:1].isspace() else -0.06
    if word == 'value':
        if prev in MORAL:
            return -0.83
        if prev in {'intrinsic', 'inherent', 'personal', 'aesthetic', 'sentimental'}:
            return -0.17
        if prev in {'we', 'you', 'i', 'they'}:
            return -0.27
        if prev in NUMERIC:
            return 0.06
        if prev in {'business', 'customer', 'shareholder', 'brand'}:
            return -0.31
        if prev in {'good', 'best', 'great', 'fair', 'more', 'to'}:
            return -0.17
        if recent & NUMERIC:
            return 0.04
        return -0.01 if token[:1].isspace() else 0.05
    if word == 'principles':
        return -0.64 if prev in GUIDING else -0.48
    if word == 'principle':
        if prev == 'in':
            return -0.12
        return -0.39 if prev in GUIDING else -0.18
    if word == 'ethics':
        return -0.29 if token.strip()[:1].isupper() else -0.47
    if word in {'ethical', 'ethic', 'morals'}:
        return -0.34
    if word in {'moral', 'morality', 'philosophy'}:
        return -0.19
    if word in {'virtue', 'ideals', 'virtues'}:
        return -0.45 if word == 'virtues' else -0.27
    if word in {'duty', 'duties', 'citizenship'}:
        return -0.22
    if word == 'accordance':
        return -0.15
    if word in {'norms', 'standards', 'conduct', 'beliefs', 'rights'}:
        return -0.07
    if word in CHINESE:
        if '核心' in prev and word in {'价值', '价值观'}:
            return -0.74 if word == '价值' else -1.32
        return CHINESE[word]
    if word == 'of':
        if prev == 'principles':
            return -0.44
        if prev in {'principle', 'ethics', 'virtue', 'virtues', 'duty'}:
            return -0.23
        if prev == 'values':
            return -0.30 if recent & CULTURE else -0.08
        if prev == 'importance':
            return -0.15
    if word == 'be' and prev in {'should', 'must', 'shall'}:
        return -0.10
    if word == 'should':
        return -0.09 if prev in {'we', 'you', 'they', 'people', 'one'} else -0.015
    if word == 'to' and prev in {'important', 'essential', 'ought', 'duty'}:
        return -0.14
    if word == 'code' and token[:1].isspace():
        return 0.09 if prev in {'exit', 'source'} else -0.09
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ()
    token = prefix.token_strings[-1]
    value = response(token, history)
    history = (history + (token.strip().lower(),))[-12:]
    return (doc, history), value

programs.haiku:
"""Moral-principle vocabulary detector for component layers.0.mlp.down_proj:1959.

The component writes a negative amount into the residual stream on words of normative
ethics: "principles", "ethics"/"ethical", "morals"/"morality", "moral", "duty", "virtue",
"citizenship", and their Chinese counterparts (价值观, 价值, 理念, 原则, 精神, 德, 道德).
"values" and "value" count only in the moral sense: "values" after a moral modifier
("core values", "societal values") is strongly negative, other "values" mildly negative,
and "value" is near zero unless it follows such a modifier (technical "value" is zero).
Everything else is about zero.

The program predicts that activation: a fixed negative number per word family.
"""

READS = ()

# English normative-ethics words, typical activation
PRINCIPLES = {"principles": -0.5, "principle": -0.17}
ETHICS = {"ethics": -0.38, "ethical": -0.32, "ethic": -0.45, "morals": -0.3, "morality": -0.17,
          "moral": -0.19, "virtue": -0.26, "dignity": -0.16, "philosophy": -0.17,
          "citizenship": -0.22}
DUTY = {"duty": -0.2, "duties": -0.26}
# Chinese counterparts
CHINESE = {"价值观": -0.9, "价值": -0.2, "理念": -0.2, "原则": -0.33, "精神": -0.34,
           "德": -0.17, "道德": -0.26, "社会主义": -0.22, "忠诚": -0.18}
WEIGHTS = {**PRINCIPLES, **ETHICS, **DUTY, **CHINESE}

# words that, just before "value(s)", make it the moral sense of the word
MORAL_MODIFIERS = {"core", "our", "moral", "family", "societal", "cultural", "traditional",
                   "organizational", "personal", "ethical", "human", "shared", "their", "your",
                   "social", "community", "democratic", "christian", "religious", "universal"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word == "values":
        return carry, (-0.9 if before in MORAL_MODIFIERS else -0.1)
    if word == "value":
        return carry, (-0.3 if before in MORAL_MODIFIERS else 0.0)
    return carry, WEIGHTS.get(word, 0.0)

programs.luna:
"""Recognize words about values, ethics, and guiding principles.

Words naming principles or ethical conduct are strong examples in the
component's corpus windows.  Common, ambiguous words like "value" get a
smaller prediction; most other words receive no contribution.  This is a
lexical cue, not a claim that the rule understands the surrounding argument.
"""

READS = ()

STRONG_ETHICAL_WORDS = {
    "principles", "ethical", "ethics", "ethos", "morality", "virtue",
    "duties", "citizenship", "adherence", "respect",
