programs.haiku:
"""Activation of layers.0.mlp.down_proj:1960 (a future/disposal-marker detector).

It fires on the word that introduces a verb phrase about the future or about doing something
to an object: Chinese 将 (future "will"; strongest when it is the marker itself, weaker in
compounds like 将其 or 将近), 把 (disposal "take X and ..."), 使/令 (causative "make"), 要/就/已,
and English "will", "would", "'ll", "shall", "keep". Ordinary modal verbs (can, may, should,
must, 可以, 能) do not fire. Everything else is 0.
"""

READS = ()

# Activation for the marker tokens, as typical values measured on web text
FUTURE_CHINESE = {"将": 7.0, "將": 7.2, "我们将": 6.8, "都将": 7.2, "也将": 6.0}
WORDS = {
    "will": 1.0, "would": 0.8, "shall": 0.6, "'ll": 0.8, "’ll": 0.8, "'d": 0.5, "’d": 0.5,
    "keep": 0.8, "keeps": 0.8, "kept": 0.8, "keeping": 0.8,
}
OTHER_CHINESE = {"把": 3.2, "我把": 2.8, "要": 0.75, "就": 0.9, "已": 0.9, "使": 0.8, "令": 0.7, "会": 0.3}


def token_value(token):
    word = token.strip().lower()
    if token in FUTURE_CHINESE:
        return FUTURE_CHINESE[token]
    if "将" in token or "將" in token:
        return 3.5  # 将其, 将在, 将会, 将近 ... (compounds)
    if token in OTHER_CHINESE:
        return OTHER_CHINESE[token]
    return WORDS.get(word, 0.0)


def step(carry, prefix, upstream):
    return None, float(token_value(prefix.token_strings[-1]))

