programs.sol:
"""A local spelling signal after J/j, Arabic jeem, or Tajik che.

It is strongest and negative on short vowel-led fragments, especially e-led
ones. Longer fragments attenuate it; repeating the preceding letter raises
the prediction. Whitespace and closing punctuation mostly stop the signal.
The first few positions of a document receive a small boost. The rule was
fit to training activations; it does not reproduce token-specific variation.
"""
import unicodedata

READS = ()
VOWEL_OFFSETS = {'a': -0.36, 'e': -0.76, 'i': -0.51,
                 'o': -0.37, 'u': -0.14}


def after_j(token, previous_letter="j"):
    if not token:
        return 0.0
    c = token[0]
    if c.isspace():
        return -0.17 if previous_letter == 'j' else -0.07
    if not c.isalpha() and previous_letter in token.lower():
        return 0.9
    if c.isdigit():
        return -0.83
    if not c.isalpha():
        if c in '.)]};':
            return -0.05
        return -0.29 if c in '=:+-(*<' else -0.14
    plain = unicodedata.normalize('NFD', c.lower())[0]
    length = len(token)
    value = -0.60 + 0.11 * (min(6, length) - 1)
    if plain in VOWEL_OFFSETS:
        value += VOWEL_OFFSETS[plain]
        value += 0.10 * max(0, min(7, length) - 3)
    if plain == 'e' and length <= 3:
        value -= 0.23
    if previous_letter in token.lower():
        value += 1.55
    if token.isupper():
        value -= 0.11
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = unicodedata.normalize('NFKC', prefix.token_strings[-1])
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        previous, position = carry[1], carry[2] + 1
    last = previous.lower().rstrip('\x00')[-1:]
    value = 0.0
    if last in ('j', 'ج', 'ҷ'):
        value = after_j(token, last)
        value *= 1.0 + 0.35 * 2.0 ** (-position / 5.0)
    return (doc, token, position), float(value)

programs.luna:
"""Recognize a hash marker at the start of a document.

The component's rare, large positive responses in the inspected corpus occur on
the first hash-mark token of a document. A single hash has the larger response;
a double hash has a smaller one. Other positions get zero.
"""

READS = ()


def step(carry, prefix, upstream):
    """Return a fixed response for a leading # or ##, otherwise zero."""
    t = prefix.position
    first_in_document = (
        t == 0
        or prefix.document_ids[t] != prefix.document_ids[t - 1]
    )
    if first_in_document:
        token = prefix.token_strings[t]
        if token == "#":
            return None, 1.888671875
        if token == "##":
            return None, 0.63037109375
    return None, 0.0

programs.sol:
"""Detect 'type' and the vocabulary of classification, with negative output.

The strongest response is to the singular word, including code punctuation.
Plurals, compounds, split word pieces, and translations are weaker. Kind,
category, and genre are weak signals. A smaller response extends to 'of'
and separators just after a classification word. Other tokens are zero.
"""
import re

READS = ()


def type_signal(token):
    # Discard a token's leading whitespace and code delimiters, not its letters.
    word = re.sub(r'^[\W_]+', '', token)
    lower = word.lower()
    if lower == 'type':
        if token == word:
            return -6.1 if word == 'Type' else -5.8
        if token.startswith('_'):
            return -4.8
        if token.startswith('-') and word == 'Type':
            return -5.8
        return -5.3
    if lower == 'types':
        if token.startswith('-'):
            return -4.5
        return -3.9 if token == 'Types' else -3.6

    # Common word pieces left when 'type' is split across tokens.
    pieces = {'typ': -2.6, 'ype': -3.0, 'ypes': -3.3,
              'yp': -0.45, 'ty': -0.6, 'yped': -1.3,
              'otype': -2.4, 'otypes': -2.4, 'otyp': -1.8,
              'otyping': -1.4}
    if lower in pieces:
        return pieces[lower]

    # These compounds are distinct familiar uses of the type stem.
    compounds = {'typeof': -2.6, 'typing': -2.3, 'typed': -2.3,
                 'typescript': -1.4, 'typedef': -1.2, 'typename': -1.6,
                 'typeerror': -2.7, 'typo': -1.0, 'subtype': -2.6,
                 'genotype': -1.8, 'phenotype': -0.8,
                 'prototype': -0.35, 'stereotype': -0.65,
                 'stereotypes': -0.65, 'isinstance': -2.8}
    if lower in compounds:
        if word in {'TypeOf', 'TypeName'}:
            return -3.8
        return compounds[lower]
    if lower in {'prototypes', 'phenotypes', 'genotypes'}:
        return compounds[lower[:-1]]
    if lower == 'typeid':
        return -2.9
    if lower == 'astype':
        return -2.6
    if lower.endswith(('type', 'types')):
        if token.startswith('.'):
            return -3.1
        return -3.4 if token[:1].isspace() else -3.9

    # Classification words in English and several common translations.
    if lower in {'kind', 'kinds', 'category', 'categories'}:
        return -0.85
    if lower == 'genre':
        return -1.15
    if lower in {'tipo', 'tipos', 'тип', 'типа', 'типу', 'типе',
                 'типов', 'типы', 'kiểu'}:
        return -2.1
    if word.startswith('类型'):
        return -3.8 if word == '类型' else -3.3
    if word == '型':
        return -2.6
    if word.endswith('型'):
        return -1.5
    if word == 'タイプ':
        return -3.2
    if word == 'نوع':
        return -2.5
    if word in {'類', '类'}:
        return -0.45
    if word in {'类别', '各类'}:
        return -1.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = type_signal(token)
    previous_word = re.sub(r'^[\W_]+', '', previous).lower()
    if token.strip().lower() == 'of':
        value = {'type': -1.06, 'types': -0.62, 'kind': -0.60,
                 'kinds': -0.24, 'instance': -0.22}.get(previous_word, value)
    elif previous_word == 'type':
        value = {'="': -0.39, '":': -0.26, ':': -0.12}.get(token, value)
    return (doc, token), value

programs.luna:
"""Detects type words, with a small extra cue for the phrase 'type of'."""
READS = ()

CATEGORY_WORDS = {
    "category", "categories", "kind", "kinds", "class", "classes",
    "genre", "genres", "sort", "sorts", "variety", "varieties",
    "form", "forms", "genotype", "phenotype", "ethnicity",
    "отип", "тип", "型", "類",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    document = prefix.document_ids[-1]
    follows_type = carry is not None and carry == (document, True)

    if word == "type":
        value = -5.0
    elif word == "types":
        value = -3.5
    elif "type" in word:
        value = -4.0
    elif word in CATEGORY_WORDS:
        value = -1.0
    elif follows_type and word == "of":
        value = -0.7
    else:
        value = 0.0

    return (document, "type" in word), value

programs.sol:
"""A token-level degree/quantity detector, strongest for 'very'.

Translations of 'very' also respond strongly. Comparatives, quantities and
milder intensifiers respond weakly. Chinese tokens containing an intensifier
plus another word have a lower response than the intensifier alone.
Selected adjacent-token negations and quantity questions attenuate responses.
English 'very' is also weaker at the start of a document.
This approximates lexical responses, not full sentence meaning.
"""
READS = ()

# Translations of 'very', with language-specific response strengths.
VERY = {
    'sehr': 5.4,
    'très': 5.8,
    'muy': 5.3,
    'очень': 5.9,
    'rất': 6.2,
    'molto': 3.8,
    'muito': 3.5,
    'bardzo': 3.2,
    '매우': 5.3,
    'とても': 4.0,
    '非常に': 4.6,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    previous = "" if new_document else carry[1]
    negated = previous in {"not", "never", "n't", "n’t", "'t", "’t"}
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    if lower == 'very':
        value = 10.0 if token == ' very' else 9.5
        if token == 'very':
            value = 7.6
        if negated:
            value -= 2.0
        elif new_document:
            value *= 0.7
    elif word == '非常':
        value = 7.4
    elif word != '非常に' and '非常' in word:
        value = 6.0 if word.endswith('非常') and len(word) < 4 else 4.0
    elif '很' in word:
        if word == '很':
            value = 7.0
        elif '不' in word:
            value = 2.9
        elif word.endswith('很'):
            value = 5.8 if len(word) < 3 else 4.3
        elif word.endswith(('很是', '很有')):
            value = 5.0
        else:
            value = 2.9
    elif word.endswith('最'):
        value = 1.6
    elif word in {'极', '十分'} or lower == 'exceedingly':
        value = 2.8
    elif word == '極' or lower == 'incredibly':
        value = 2.1
    elif lower == 'extremely':
        value = 3.9
    elif lower in {'really', 'quite'}:
        value = 1.5
        if negated:
            value = 0.95 if lower == 'really' else 0.6
    elif lower == 'highly' or word in {'许多', '特别'}:
        value = 1.4
    elif lower == 'more':
        value = 0.5 if previous == 'no' else 0.95
    elif lower in {'lots', 'plenty'} or word == '更加':
        value = 1.0
    elif lower == 'many':
        value = 0.9
        if previous == 'how':
            value = -0.05
        elif previous == 'too':
            value = 0.3
        elif previous in {'so', 'as'}:
            value = 0.6
    elif lower in {'most', 'pretty', 'somewhat'} or word == '更':
        value = 0.75
    elif lower == 'less':
        value = 0.63 if token.startswith(' ') else 0.2
    elif lower == 'much':
        value = 0.8
        if previous in {'how', 'pretty'}:
            value = -0.2
        elif previous in {'too', 'not'}:
            value = 0.2
        elif previous in {'so', 'as'}:
            value = 0.3
    elif lower == 'lot':
        value = 0.4
    else:
        value = VERY.get(lower, 0.0)
    return (doc, lower), float(value)

programs.haiku:
"""Degree intensifiers: this component fires on "very" and its equivalents.

It reads only the current token: no state and no context. Its strongest response
is to English "very" (about 10). Translations of "very" respond at about 5:
Chinese 很 and 非常 on their own, Russian очень, French très, Spanish muy,
German sehr, Vietnamese rất, Korean 매우, Italian molto, Portuguese muito,
Japanese とても, and so on. Chinese 很 / 非常 inside a longer word (很多, 很快,
很好) respond more weakly, at about 3. Other strong degree words respond at
about 2.5 (extremely, incredibly, 十分, 极, 甚). Weaker "a lot / high degree"
words respond at about 1 (highly, really, quite, more, most, many, much, less,
pretty, 最). Every other token gives 0.
"""

READS = ()

VERY_TRANSLATIONS = {
    "很", "非常", "очень", "très", "muy", "sehr", "매우", "rất", "아주", "molto",
    "muito", "bardzo", "весьма", "とても", "sangat",
}
STRONG_DEGREE = {"extremely", "incredibly", "tremendously", "十分", "极", "極", "甚"}
WEAK_DEGREE = {
    "highly", "really", "quite", "beaucoup", "more", "most", "many", "much",
    "less", "pretty", "lots", "plenty", "somewhat", "fairly", "最", "更加",
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    if word == "very":
        value = 10.0
    elif word in VERY_TRANSLATIONS:
        value = 5.0
    elif "很" in raw or "非常" in raw:
        value = 3.0
    elif word in STRONG_DEGREE:
        value = 2.5
    elif word in WEAK_DEGREE:
        value = 1.0
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Approximate a sparse word feature for comparison and degree.

It scores ordinary comparison words modestly and the clearest words for
"very" more strongly, without trying to interpret their sentence context.
"""

READS = ()

COMPARISONS = frozenset({
    "more", "most", "less", "least", "many", "much", "better", "best",
    "greater", "greatest", "further", "farthest", "более", "больше",
    "менее", "меньше", "许多", "很多", "更", "最", "很少",
})
VERY_WORDS = frozenset({"very", "очень", "非常", "很"})
DEGREE_WORDS = frozenset({
    "quite", "rather", "pretty", "too", "enough", "especially",
    "particularly", "highly", "deeply", "extremely", "really", "fairly",
    "somewhat", "relatively", "tremendous", "ultra", "довольно", "крайне",
