programs.sol:
"""A small surface-word-fragment approximation.

Predict negative contributions for Japanese loanword endings, especially
ソ + ース (source/sauce) and ニュ + アル (as in manual). Russian -ит
fragments are positive, especially after stems for looking, producing,
and serving; endings of 'capable' are also positive. Predict a small
negative value for the English -ed fragment and near zero elsewhere.
These rules capture selected lexical peaks, not the component's diffuse
background variation or a general grammatical category.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ""
    value = 0.0005
    if token.startswith("ー"):
        value = -0.075
        if token == "ース" and previous.endswith("ソ"):
            value = -0.73
        elif token == "ール" and previous.endswith("ロ"):
            value = -0.24
    elif token == "アル":
        value = -0.15
        if previous.endswith("ニュ"):
            value = -0.60
    elif token.startswith("ッ"):
        value = -0.04
    elif token == "ит":
        value = 0.09
        if previous.endswith("гляд"):
            value = 0.435
        elif previous.strip() == "производ":
            value = 0.32
        elif previous.strip() == "служ":
            value = 0.47
    elif previous.strip() == "способ":
        if token in {"ны", "на"}:
            value = 0.34
        elif token == "ен":
            value = 0.19
    elif token == "ed" and previous and previous[-1].isalpha():
        value = -0.022
    return (doc, token), value

"""Lexical local-family signal, including code and Chinese.

'Local' is the dominant negative feature. Its derivatives and translations
have smaller responses, as do words about social/personal/geographic scope.
Punctuation attached to 'local' changes its amplitude. This current-token
approximation ignores contextual strength changes and split-word continuations.
Other tokens are zero.
This recognizes vocabulary, not whether a place is actually near the speaker.
"""
READS = ()

SCOPE_WORDS = {
    'social', 'global', 'remote', 'regional', 'nearest',
    'neighbor', 'neighbors', 'neighbour', 'neighbours', 'neighborhood',
}
LOCAL_DERIVATIVES = {
    'locals', 'locality', 'localities', 'localize', 'localized',
    'localizing', 'localization', 'localisation', 'localised',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    stripped = token.strip()
    word = stripped.strip('_-/.,;:()[]{}').lower()
    if word == 'local':
        if stripped.startswith('/'):
            value = -8.9
        elif stripped.startswith('.'):
            value = -6.2
        elif stripped.startswith('('):
            value = -4.8
        elif stripped.startswith('_') or token.startswith('\t'):
            value = -6.7
        elif stripped.startswith('-'):
            value = -7.4
        else:
            value = -7.6 if token.startswith(' ') else -7.9
    elif word == 'locally':
        value = -5.0
    elif word in LOCAL_DERIVATIVES:
        value = -3.0
    elif word.startswith('local'):
        # Locale, localhost and compounds like localStorage / LocalDate.
        value = -2.1
    elif word in {'loc', 'ocal', 'lok', 'мест'}:
        # Local-root fragments, including German and Russian spellings.
        value = -1.5
    elif word.startswith('lokal'):
        value = -3.6
    elif word.endswith('local'):
        # Code identifiers such as ToLocal and getLocal.
        value = -5.5
    # Chinese: local, local people, native land, and a local part.
    elif word == '本地':
        value = -5.0
    elif word in {'当地', '当地人', '当地的'}:
        value = -4.0
    elif word == '當地':
        value = -3.1
    elif word in {'本土', '局部'}:
        value = -2.7
    elif word == 'nearby':
        value = -1.4
    elif word in {'personal', 'neighbourhood', '附近', '身边'}:
        value = -1.1
    elif word in SCOPE_WORDS:
        value = -0.85
    elif word in {'cultural', 'scale', 'scales', '邻居', '全球', '个人'}:
        value = -0.6
    else:
        value = 0.0
    return None, value

programs.luna:
"""Estimate a word-level signal for local scope and human connections.

Local/locality words have the clearest, strongest response. Personal and social
relations, distance, neighborhood, and broader geographic scope get a smaller
response. This compact vocabulary model misses other contexts and usages.
"""
READS = ()

LOCAL_WORDS = {
    "local", "locally", "locale", "locality", "localities",
    "localized", "localised", "localize", "localise", "当地",
}
RELATION_OR_SCOPE_WORDS = {
    "personal", "social", "remote", "global", "regional", "cultural",
    "neighborhood", "neighbourhood", "neighbor", "neighbour", "neighbors",
    "neighbours", "nearest", "nearby", "scale", "scales", "邻居", "zial",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip(
        " \t\r\n.,:;!?()[]{}\"'`<>/\\_"
    ).casefold()
    if word in LOCAL_WORDS:
        return None, -6.0
    if word in RELATION_OR_SCOPE_WORDS:
        return None, -0.8
    return None, 0.0

"""A few lexical cues predict this component's occasional positive pulses.

The clearest cue is the token piece ``inter`` itself; related words containing
that spelling are weaker. Tokens for between/within and alternatives make
smaller predictions, as do interval/integral words. Most tokens get zero.
"""

READS = ()

RELATION_WORDS = {
    "between", "within", "among", "amongst", "entre", "zwischen",
    "dentro", "между", "之间", "之間", "間", "互",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower().strip()

    if token == "inter":
        return None, 6.5
    if "inter" in token:
        return None, 1.9
    if token in RELATION_WORDS:
        return None, 1.1
    if token.startswith("alternat"):
        return None, 1.5
    if token.startswith(("interval", "integral", "integer", "integrat")):
        return None, 0.7
    return None, 0.0

programs.haiku:
"""Negation scope: the word right after a negation that narrows or intensifies it.

layers.0.mlp.down_proj:1969 is a "not only / not just" detector. Its activation is near
zero almost everywhere, but it spikes on the word that directly follows a negation
("not", "n't", "no", "non", "never", "neither", "cannot", or their translations) when
that word is a restrictor or intensifier:

  * "only" / "just" after a negation ("not only", "isn't just", "not just a"): about 8;
  * other quantifiers and degree adverbs ("always", "all", "every", "exactly",
    "necessarily", "entirely", "very", "so", "merely", "solely", ...): about 4;
  * code and technical words ("not null", "non-zero", "equal", "sure", "limited",
    "one", "even", ...): about 1.5;
  * "just" or "only" after "than" ("more than just"): about 4, and "than" after a
    comparative ("more than") gets a weak 0.8.

Every other position predicts 0. Negation is the word before, within the same document,
so the rule is one word of left context and no state.
"""

READS = ()

NEGATIONS = {
    "not", "no", "never", "non", "neither", "nor", "cannot", "n't", "’t", "'t",
    "не", "不", "没", "nicht", "nie", "nein", "không", "sin", "ne", "nem",
}
ONLY_JUST = {
    "only", "just", "solo", "solely", "merely", "simply", "purely", "nur", "seulement",
    "tylko", "только", "просто", "chỉ", "只",
}
INTENSIFIERS = {
    "always", "all", "every", "exactly", "necessarily", "entirely", "fully", "completely",
    "very", "so", "alone", "sempre", "tutti", "完全", "直接",
}
TECHNICAL = {
    "null", "nil", "zero", "-zero", "equal", "limited", "sure", "even", "one", "as",
    "until", "easy", "immediately", "guaranteed", "empty", "none", "sufficient", "longer",
    "clear", "mean", "match", "already", "really", "quite", "much", "possible",
}
COMPARATIVES = {"more", "less", "higher", "greater", "larger", "longer", "better"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    before = _word(prefix.token_strings[-2])
    word = _word(prefix.token_strings[-1])
    if before in NEGATIONS:
        if word in ONLY_JUST:
            return None, 8.0
        if word in INTENSIFIERS:
            return None, 4.0
        if word in TECHNICAL:
            return None, 1.5
        return None, 0.0
    if before == "than" and word in ONLY_JUST:
        return None, 4.0
    if before in COMPARATIVES and word == "than":
        return None, 0.8
    return None, 0.0

programs.luna:
"""Track common comparison, quantity, and negative-degree phrases."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    document = prefix.document_ids[-1]
    previous, previous_document = carry or ("", None)
    before = previous.strip().lower() if previous_document == document else ""

    if word == "only" and before == "not":
        value = 8.0
    elif word == "than" and before == "more":
        value = 0.8
    elif word == "one" and before in {"least", "exactly", "only"}:
        value = 0.7
    elif word == "three" and before == "all":
        value = 0.55
    elif word == "very" and before == "not":
        value = 2.8
    elif word == "longer" and before == "no":
        value = 1.3
    elif word == "full" and before == "neither":
        value = 1.6
    else:
        value = 0.0
    return (token, document), value

programs.haiku:
"""The documentary record of the past, as a negative signal.

Layer-0 MLP output component 1970 goes negative on words that name the documentary record
of the past: historians and their biographies, archives, documented facts, chronicles,
testimony and witnesses, museums, relics, memorials, and the plural nouns records,
documents, sources and evidence. Most other tokens give almost nothing. Plain "history",
"record", "document" and "memory" are not reliably negative, so they are left at zero.

The program reads the current word (lower-cased, leading space removed) and predicts a
negative value in three tiers, the most specific historical-record words strongest. The
value doubles when the word follows an adjective of officialdom or history ("historical
record", "official documents"). The tier values sit near the average activations measured
on training text (about -0.3, -0.2 and -0.1). Every other token predicts 0.
"""

# Strongest: historians, their biographies and the archives and testimony they use.
STRONG = {
    "historian", "historians", "biography", "archives", "archival", "archived",
    "documented", "chronicle", "chronicles", "relics", "relic", "testimony",
    "testified", "witness", "witnesses", "资料", "資料",
}
# Middle: the documentary record itself and the places that keep it.
MEDIUM = {
    "records", "documents", "sources", "museum", "museums", "evidence", "memorial",
    "monument", "monuments", "photographs", "photograph", "documentary", "census",
    "preserved", "authentic", "officially", "official", "heritage", "artifacts",
    "artifact", "archae", "dating", "archive",
}
# Weakest: recorded, detailed and historic-sense words, and the Chinese for "history" and "record".
WEAK = {
    "recorded", "memories", "historic", "details", "detailed", "史", "记", "記",
}
VALUE = {"strong": -0.35, "medium": -0.2, "weak": -0.1}
BOOSTED_BY = {"historical", "official", "public", "factual", "primary", "national"}

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in STRONG:
        value = VALUE["strong"]
    elif word in MEDIUM:
        value = VALUE["medium"]
    elif word in WEAK:
        value = VALUE["weak"]
    else:
        return carry, 0.0
    if len(prefix.token_strings) > 1:
        if prefix.token_strings[-2].strip().lower() in BOOSTED_BY:
            value *= 2
    return carry, value

"""Layer 0, MLP down-projection, component 1971.

What it does: this component is nearly silent. Its activation is small (sd about 0.03)
and it almost never matters to the output. Most of its variance is specific to each
token and cannot be stated as a concept, so this program captures only a few coarse
word-class patterns, each as the mean activation observed for that class:

  - chat/tool markers such as <tool_call>, <|endoftext|>:   about +0.02
  - identifiers with an underscore (snake_case names):       about +0.01
  - CJK characters:                                           about -0.005
  - digits:                                                   about -0.003
  - word-continuation pieces (letters, no leading space):     about -0.004
  - capitalised words after a space (names):                  about -0.004
  - everything else:                                          about 0

READS = () and the program keeps no state between tokens.
"""

MARKERS = {"<tool_call>", "</tool_response>", "<|endoftext|>", "<|im_end|>", "<|im_start|>"}

READS = ()


def is_cjk(s):
    return any("一" <= c <= "鿿" for c in s)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    word = s.strip()
    if s in MARKERS:
        v = 0.023
    elif is_cjk(s):
        v = -0.005
    elif word.isdigit():
        v = -0.003
    elif "_" in s:
        v = 0.009
    elif word.isalpha() and not s.startswith(" "):
        v = -0.004
    elif word[:1].isupper():
        v = -0.004
    else:
        v = 0.0
    return carry, float(v)

programs.sol:
"""Approximate an -ing continuation feature using spelling and word classes.

After a token ending in 'ing', predict negative values for 'of', common
noun heads of participial compounds, and letters extending the word.
Determiners and verb particles instead get small positive values.
Ordinary non-inflectional 'ing' words are excluded from the strong rule.
There are weaker '-ings', '-ng', and 'which of' rules. Whitespace, case,
common suffixes, and a few lexicalized gerunds adjust the class averages.

Only the previous token is remembered, with a reset at document changes.
This captures a pattern, not all lexical or contextual activation variation.
"""

READS = ()

NONVERBAL_ING = set('''
thing something anything nothing everything string substring spring
king ring wing sing bring fling cling swing sting ceiling sibling sterling
beijing offspring
'''.split())
DETERMINERS = set('''
an this that these those my your his her its our their any some each every no
'''.split())
PRONOUNS = set('i me you he him she her it we us they them'.split())
PREPOSITIONS = set('''
at for from with by as into onto upon over under about through during
after before without between among against
'''.split())
CONJUNCTIONS = set('and or but if while because although whereas so than whether'.split())
AUXILIARIES = set('''
is are was were be been being am have has had do does did will would can
could shall should may might must
'''.split())
PARTICLES = set('up out off back away down around'.split())
# Noun heads in familiar participial compounds: floating point, living room,
# working directory, parking lot, baking soda, and related noun phrases.
NOUN_HEADS = set('''
room rooms table tables directory directories point points field fields
lot lots time times date dates company companies group groups capital
price prices calculator calculators soda board boards rate rates force
forces number numbers order orders cost costs supply supplies driver drivers
'''.split())


def after_ing(token, fragment):
    word = token.strip().lower()
    # Without a separating space, letters extend the word or identifier.
    if not token[:1].isspace():
        if word in {'en', 'er', 'est'}:
            return -2.4
        if word == 'ly':
            return -1.45
        if token == '.T':  # Go's testing.T type
            return -3.5
        if word in {'.com', '.net'}:
            return -1.5
        if token.isalpha() and not word.endswith('ing'):
            return -1.2 if token[0].isupper() else -1.0
    if word == 'of':
        return -1.8 if fragment else -1.2
    if word == 'the':
        return 0.39 if fragment else 0.22
    if word == 'a' or word in DETERMINERS:
        return 0.17 if fragment else 0.11
    if word == 'to':
        return -0.02
    if word == 'in' or word == 'on' or word in PREPOSITIONS:
        return 0.05
    if word in PARTICLES:
        return 0.34 if fragment else 0.19
    if word in CONJUNCTIONS:
        return -0.46 if fragment else -0.32
    if word in AUXILIARIES:
        return -0.31 if fragment else -0.22
    if word in PRONOUNS:
        return 0.08 if fragment else -0.03
    if not word:
        return -0.11
    if token.startswith('_'):
        return -0.60
    if token.startswith('-') and any(c.isalpha() for c in token):
        return -1.25
    if not any(c.isalpha() for c in token):
        if token.startswith(','):
            return -0.22
        if token.startswith(('.', '?', '!')):
            return 0.0
        return -0.10
    if token[:1].isspace():
        return -0.85 if word in NOUN_HEADS else -0.07
    if word.endswith('ing'):
        return 0.07
    return -0.90


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    value = 0.0
    if carry is not None and carry[0] == doc:
        previous = carry[1]
        word = previous.strip().lower()
        if word.endswith('ing') and word not in NONVERBAL_ING:
            value = after_ing(token, not previous[:1].isspace())
            if previous.startswith(' ') and token.strip().lower() == 'of':
                if word in {'beginning', 'understanding', 'reading', 'training',
                            'manufacturing', 'engineering', 'marketing'}:
                    value = -0.75
                elif word in {'meaning', 'consisting'}:
                    value = -0.15
                else:
                    value = -1.65
        elif word.endswith('ings') and token.strip().lower() == 'of':
            value = -0.40
        elif (word.endswith('ng') or word.endswith('инг')) and not token[:1].isspace():
            value = -0.19 if token.isalpha() else 0.0
        elif word == 'which' and token.strip().lower() == 'of':
            value = -1.25 if 'W' in previous else -0.60
    return (doc, token), float(value)

"""A spelling detector for ON and especially ONT, with local phrase modulation.

Short tokens ending in 'ont' are strongly negative; longer related spellings
are weaker.  The English word 'on' is negative except in dependency/focus
phrases ('based on', 'depending on').  'Go on' strengthens it instead.
Smaller rules cover neighboring spellings, font/holy vocabulary across
scripts, and the German preposition 'auf'. Unrecognized tokens predict zero.
Only the last two tokens from the same document are used for phrase context;
case, token boundaries, and document starts also matter. These surface rules
do not assert that every triggering word has one shared meaning.
"""
READS = ()

# The consonant before ONT modulates the strength of that letter-group.
ONT_STRENGTH = {
    'cont': 2.3, 'dont': 2.35, 'pont': 2.9,
    'kont': 2.9, 'sont': 1.2, 'front': 0.9, 'ront': 2.0,
    'vont': 2.1, 'wont': 1.8,
}
DEPENDENCY = {
    'based': 0.12, 'depend': 0.23, 'depends': 0.38,
    'depending': 0.42, 'depended': 0.3, 'dependent': 0.21, 'dependence': 0.03,
    'relied': 0.0, 'rely': 0.32, 'relies': 0.33, 'relying': 0.5, 'reliance': 0.0,
    'focussed': 0.15, 'focus': 0.21, 'focuses': 0.38, 'focused': 0.15, 'focusing': 0.4,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    bare = token.strip()
    word = bare.lstrip('._/(-').lower()
    boundary = bool(token[:1].isspace())
    previous = ''
    earlier = ''
    start = len(prefix.token_ids) == 1 or (
        prefix.document_ids[-2] != prefix.document_ids[-1]
    )
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip().lower()
        if (len(prefix.token_ids) > 2 and
                prefix.document_ids[-3] == prefix.document_ids[-1]):
            earlier = prefix.token_strings[-3].strip().lower()

    value = 0.0
    if word == 'on':
        if bare != bare.lstrip('._/(-'):
            value = -1.1
        elif bare == 'On':
            value = -2.05 if start else (-1.35 if boundary else -1.4)
        elif start:
            value = -1.52 if boundary else -0.8
        elif not boundary:
            value = -1.0 if previous and not previous[-1].isalnum() else -0.22
        else:
            value = -1.03
            if previous in DEPENDENCY:
                value = DEPENDENCY[previous]
            elif earlier in DEPENDENCY and (previous.endswith('ly') or
                                            previous in {'only', 'more', 'less'}):
                value = 0.1
            elif previous in {'dependency', 'centered', 'centred', 'centers',
                              'concentrate', 'concentrating', 'operates', 'operate'}:
                value = -0.1
            elif previous in {'go', 'goes', 'went', 'gone'}:
                value = -1.9
            elif previous in {'printed', 'released', 'distributed', 'aired'}:
                value = -1.6
            elif previous == 'going':
                value = -1.42
            elif previous in {'work', 'works', 'worked', 'working',
                              'information', 'research', 'studies'}:
                value = -0.66
            elif previous in {'impact', 'influence', 'acting', 'acts',
                              'attack', 'attacks', 'constraints', 'restrictions'}:
                value = -0.25
            elif previous in {'effect', 'effects', 'pressure', 'emphasis',
                              'click', 'clicking'}:
                value = -0.46
    elif word == 'ont':
        value = -3.05 if boundary else -5.3
        if bare[:1] == 'O' and bare != 'ONT':
            value = -4.05
    elif word == 'mont':
        value = -4.6 if bare[:1] == 'M' or not boundary else -3.5
    elif word == 'font':
        value = -3.55 if boundary and bare[:1] == 'f' else -4.4
        if bare.startswith(('(', '/', '-')):
            value = -3.1
    elif word == 'pont' and bare[:1] == 'P':
        value = -3.4
    elif word in ONT_STRENGTH:
        value = -ONT_STRENGTH[word]
    elif word in {'onto', 'onta', 'onte'}:
        value = -2.0 if word == 'onto' else -3.1
    elif word.startswith('ontolog'):
        value = -1.8
    elif word == 'ontario':
        value = -2.4
    elif word == 'fonts':
        value = -3.1
    elif word.endswith('font'):
        value = -2.0
    elif len(bare) > 4 and bare[:4].lower() == 'font' and bare[4].isupper():
        value = -1.6
    elif word in {'字体', '字體'}:
        value = -2.25
    elif word in {'フォ', 'ント'}:
        value = -0.8 if word == 'フォ' else -0.36
    elif word == 'monte':
        value = -2.25
    elif word.startswith('mont') and not word.startswith('month'):
        value = -0.8
    elif word.startswith('contour'):
        value = -1.05
    elif word.startswith('front'):
        value = -0.7
    elif word == 'ond':
        value = -0.94
    elif word == 'ons':
        value = -0.43
    elif word == 'ount':
        value = -1.33
    elif word in {'mount', 'mounts', 'mounted', 'mounting'}:
        value = -1.05 if word in {'mount', 'mounts'} else -0.8
    elif word in {'mountain', 'mountains'}:
        value = -0.45
    elif word in {'nt', 'unt'}:
        value = -0.3 if word == 'nt' else -0.45
    elif word == 'cant':
        value = -1.0
    elif word == 'holy':
        value = -0.55
    elif word in {'圣', '聖'}:
        value = -1.7
    elif word in {'saint', 'saints', 'paint', 'painted', 'painting'}:
        value = -0.6 if word in {'saint', 'paint', 'painted'} else -0.28
    elif word in {'sant', 'santa', 'santo'}:
        value = -0.8 if word == 'sant' else -0.6
    elif word == 'онт':
        value = -2.8
    elif word == 'конт':
        value = -1.2
    elif word == 'auf' and boundary:
        value = -0.5
    elif len(bare) > 3 and bare[:2].lower() == 'on' and \
            bare[2].isupper() and bare[3].islower():
        value = -1.1
    elif word == 'onclick':
