    return None, float(value)

programs.luna:
"""A negative lexical cue for “on” and two observed locative equivalents."""
READS = ()

ON_EQUIVALENTS = frozenset({"auf", "บน"})


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().casefold()
    if token == "on":
