programs.sol:
"""A sparse lexical-collocation detector, with negative continuation pulses.

The strongest patterns are free + common noun, left/leave + behind,
left + direction/anatomy terms, and let me/let's + a verb. 'Left' also
works as a mathematical command. A few weaker rules cover compounds
with space, information, green, and independent. Match text, including
split words; reset at document boundaries. Predict zero elsewhere,
leaving most of the small, diffuse activity unexplained.
"""
import re

READS = ()
FUNCTION_WORDS = set('a an the is are was were be been being and or but to '
                     'for in on at by with as that this it you we i he she '
                     'they my your his her their our its have has had can '
                     'would should could not so'.split())
FREE_COLLOCATIONS = set('trade space body speech press jazz flow play agency '
                        'market -market download shipping will math theory '
                        'variables french republic surface movement online '
                        'printable encyclopedia hand port state list pool form '
                        'wheel hub bie'.split())
LEFT_COLLOCATIONS = set('side sides hand turn alone most off back click '
                        'subtree arm half field'.split())
THINKING_VERBS = set('try think look suppose denote assume consider take '
                     'define search do understand explain'.split())
# Weaker, familiar technical and everyday compound phrases.
OTHER_COLLOCATIONS = {
    'space': (set('between -time agency station stations shuttle telescope '
                  'travel tourism exploration separated '
                  '-separated'.split()), -0.5),
    'information': (set('technology technologies system systems theory '
                        'society criterion'.split()), -0.6),
    'green': (set('card beans bay ery'.split()), -0.6),
    'independent': (set('variable variables predictor samples'.split()), -0.35),
}
LEAVE_FORMS = {'leave', 'leaves', 'leaving', 'left'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    match = re.search(r'([\w-]+)$', history)
    previous = match.group(1).lower() if match else ''
    value = 0.0

    if (previous == 'free' or previous.endswith('-free')
            or history.endswith(('Free', '_FREE'))):
        if word in {'throw', 'throws', 'agent', 'fall', 'falls', 'falling'}:
            value = -1.8
        elif word == 'software':
            value = -2.4 if raw.strip().istitle() else -1.5
        elif word in {'radicals', 'parameters'}:
            value = -1.5
        elif word in FREE_COLLOCATIONS or word.startswith('hold'):
            value = -1.05
        elif word in {'rate', 'rates', 'time', 'radical', '-running', '-f', 'trial'}:
            value = -0.8
        elif word in {'energy', 'spins', 'pdf', 'electricity'}:
            value = -0.5
        elif word in {'of', 'from'}:
            value = -0.28
        elif word not in FUNCTION_WORDS and any(c.isalpha() for c in word):
            value = -0.15
    elif previous in LEAVE_FORMS:
        if word == 'behind':
            value = -2.6 if previous == 'left' else -2.2
        elif previous == 'left' and word.startswith(('vent', 'over')):
            value = -1.65
        elif previous == 'left' and word in {'-hand', '-wing', 'join'}:
            value = -1.15
        elif previous == 'left' and word.startswith('atr'):
            value = -1.2
        elif word in {'out', 'with', 'aside', 'blank'}:
            value = -0.8
        elif previous == 'left' and word in LEFT_COLLOCATIONS:
            value = -0.75
        elif previous == 'left' and '|' in word:
            value = -0.5
    elif previous in {'freed', 'freeing'} and word in {'from', 'up'}:
        value = -0.5
    elif re.search(r'\blet(?:[’\']s| (?:me|you|us|him|her|them))$', history, re.I):
        if word == 'know':
            value = -0.9 if previous == 'me' else -0.65
        elif word in {'go', 'see', 'say'}:
            value = {'go': -0.78, 'see': -0.4, 'say': -0.47}[word]
        elif word in THINKING_VERBS:
            value = -0.18
    elif previous in {'let', 'letting'}:
        value = {'go': -0.68, 'alone': -0.38, 'mut': -0.23}.get(word, 0.0)
    elif previous == 'fre' and word in {'estyle', 'eway', 'eware'}:
        value = -0.8

    elif previous in OTHER_COLLOCATIONS:
        followers, strength = OTHER_COLLOCATIONS[previous]
        if word in followers:
            value = strength

    if word in {'frac', 'begin'} and re.search(
            r'\\left\s*[([{]\s*\\$', history):
        value = -1.3
    # The phrasal verb also allows an object: 'leave him behind'.
    if word == 'behind' and previous not in LEAVE_FORMS:
        if re.search(
                r'\b(?:leave|leaves|leaving|left)\b(?: [\w’\'-]+){1,6}$',
                history, re.I):
            value = -2.0 if previous in {'me', 'you', 'us', 'him', 'her'} else -1.4
    if word == 'charge' and re.search(r'\bfree of$', history, re.I):
        value = -0.5
    if word == 'of' and re.search(
            r'\bfree (?:flow|use|delivery|edges)$', history, re.I):
        value = -0.6
    if word == 'with' and re.search(
            r'\b(?:left|leaving) (?:me|him|her|us|them)$', history, re.I):
        value = -0.7
    return (doc, (history + raw)[-80:]), float(value)

programs.haiku:
"""Layer-0 MLP down_proj component 1974: a sparse, mostly-negative detector for a few
word contexts.  It is near zero almost everywhere; these rules capture only a small
part of its variance.

What it does, in plain terms:
  * After "free" / "Free" / "freed" / "freedom": a content word that continues the
    phrase (free agent, free throw, free fall, free software, free trade, free press)
    is pushed negative, about -0.4 on average.  Function words and punctuation after
    "free" (free of charge, free to, free,) stay at 0.
  * After "left" / "Left" / "leave" / "leaving": a content word (left ventricle,
    left side, left hand, left-handed, left turn) is pushed negative, about -0.35.
  * "behind" (as in "leave behind") is negative, about -0.3.
  * LaTeX commands written after a backslash, \\frac and \\begin, are negative, about -0.3.
  * Everywhere else it predicts 0, its typical value.

The constants are the mean activation of each group in training text.  Using the
groups' means is the best constant per group under squared error.
"""

READS = ()

FREE_WORDS = {"free", "freed", "freeing", "freedom", "-free", "fre"}
LEFT_WORDS = {"left", "leave", "leaving", "leaves"}
LATEX_STEMS = {"frac", "begin"}
FUNCTION_WORDS = {
    "of", "to", "and", "or", "the", "a", "an", "for", "with", "in", "from", "by",
    "on", "at", "is", "are", "was", "be", "as", "that", "it", "its", "this",
    "his", "her", "their", "our", "my", "your", "me", "him", "them", "us", "you",
    "s", "'s", "not", "but", "if", "so", "than", "can", "will", "may",
}


def _norm(s):
    return s.strip().lower()


def _is_word(s):
    return s.isalpha() or (s.startswith("-") and s[1:].isalpha())


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    cur = _norm(toks[-1])
    prev = _norm(toks[-2]) if len(toks) > 1 and docs[-2] == docs[-1] else ""
    is_content = _is_word(cur) and cur not in FUNCTION_WORDS
    if cur == "behind":
        return carry, -0.3
    if prev in FREE_WORDS and is_content:
        return carry, -0.4
    if prev in LEFT_WORDS and is_content:
        return carry, -0.35
    if prev.endswith("\\") and cur in LATEX_STEMS:
        return carry, -0.3
    return carry, 0.0

programs.sol:
"""A written-number boundary detector, strongest on attached plural endings.

The large case is 's' after a number (decades or seconds), followed by ordinals,
date counters and unit symbols. A final zero strengthens most suffixes. Spaces
weaken the response. Away from numbers, plural endings on acronyms still give
small positive predictions (using uppercase tokens as an acronym cue).
Years following spelled-out tens get a weaker number-like response.
Coefficients are rounded training averages.
"""
READS = ()
MONTHS = set('January February March April May June July August September '
             'October November December'.split())
UNITS = set('mm cm km mg kg ml hz khz mhz ghz mv kv kw mw ma pa kpa mpa '
            'b kb mb gb tb px pt em rem min sec ms ns nm mol mmol oz lb ft'.split())
DATES = {'年': .85, '月': 1.01, '日': .53, '년': .92, '월': 1.17,
         '일': .68, '号': .53, '號': .53, '天': .53, '分': .75,
         '点': .75, '點': .75, '集': .75, '章': .75, '시': .75}
TIME = set('year years month months week weeks day days hour hours '
           'minute minutes second seconds'.split())
COUNTERS = set('个個人元万萬亿億位条條家辆輛楼樓')
SHORT_MONTHS = {month[:3] for month in MONTHS}
TENS = set('twenty thirty forty fifty sixty seventy eighty ninety'.split())
HEX_LETTERS = set('abcdefABCDEF')


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, numeral = '', ''
    else:
        _, previous, numeral = carry
    number = bool(numeral) and numeral[-1].isdecimal()
    word = s.strip().lower()
    value = 0.0
    if number:
        zero = int(numeral[-1]) == 0
        digits = numeral.rsplit('.', 1)[-1]
        attached = bool(s) and not s[0].isspace()
        if s == 's':
            value = 2.1 if len(digits) == 1 else 2.55
            if zero:
                value = 3.25 if '.' in numeral else {
                    1: 2.74, 2: 3.6, 3: 3.3, 4: 3.8}.get(len(digits), 3.4)
        elif s in ("'s", '’s'):
            value = .94 + 1.08 * zero
        elif s in ('S', ' s'):
            value = (1.0 if s == 'S' else .52) + .4 * zero
        elif s in ('st', 'th', 'nd', 'rd'):
            value = {'st': 1.25, 'th': 1.18, 'nd': .86, 'rd': .76}[s]
            value += .25 * zero
        elif s == ';s':
            value = .83
        elif s == '年代':
            value = 2.3
        elif s in DATES:
            value = DATES[s] + .15 * zero
        elif len(s) > 1 and s[0] in DATES and s != '日本':
            value = .6 + .15 * zero
        elif s in COUNTERS:
            value = .35 + .2 * zero
        elif s.strip() in MONTHS:
            value = .64
        elif s.strip() in SHORT_MONTHS:
            value = .31
        elif word in ('am', 'pm'):
            value = (1.0 if attached else .38) + .25 * zero
        elif word in TIME:
            value = .16 + .18 * zero
            if word in ('year', 'years'):
                value = .47 + .35 * zero
            elif word in ('month', 'months'):
                value = .33 + .15 * zero
            elif word in ('hours', 'minutes', 'seconds'):
                value = -.07 + .15 * zero
        elif s.startswith('\\x') and len(s) > 2:
            value = -.28
        elif word == 'percent':
            value = -.25
        elif word in UNITS:
            value = .55 + .25 * zero if attached else -.1
        elif attached and s.isascii() and s.isalpha():
            value = .55 if len(s) == 1 else .4
            if set(s) <= HEX_LETTERS and not s.isupper():
                value = .3 if len(s) == 1 else -.1
            value += .25 * zero
        elif s.startswith('-') and s[1:] in TIME | {'bit', 'point', 'digit'}:
            value = .65
        elif s in ('×', '′', '″'):
            value = .43 + .35 * zero
        elif s.startswith('+'):
            value = .06 + .29 * zero
        elif s == '%':
            value = -.11 + .2 * zero
    elif s == 's':
        value = .67 if previous.strip().isupper() else .18
    elif s in ("'s", '’s'):
        value = .25 if previous.strip().isupper() else -.02
    elif s == ' s':
        value = .15
    elif word == 'percent':
        value = -.3
    elif word == 'years' and previous.strip().lower() in TENS:
        value = .36
    elif word in TIME and word.endswith('s'):
        value = -.12

    if s and s.isdecimal():
        numeral += s
    elif s == '.' and number and '.' not in numeral:
        numeral += '.'
    else:
        numeral = ''
    return (doc, s, numeral), float(value)

programs.haiku:
"""Fires on a letter suffix written straight after a number (80s, 12th, 5k, 3月),
strongest for decades and ordinals, and weakly on a bare 's' after any word."""
READS = ()

SUFFIX = {"st", "nd", "rd", "th", "s", "'s", "’s", ";s", "年", "月"}
DECADE = {"s", "'s", "’s", ";s"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    if not cur.isalpha() or cur[0] == " ":
        return carry, 0.0
    # count the digits in the number directly before this token
    n = 0
    for s in reversed(prefix.token_strings[:-1]):
        if not (len(s) == 1 and s.isdigit()):
            break
        n += 1
    if n == 0:
        # a bare suffix 's' after a word (plural or possessive) is weakly positive
        return carry, 0.15 if cur in DECADE else 0.0
    value = 0.45 * (1.0 if n == 1 else 2.0)
    if cur in SUFFIX:
        value *= 2.0
    return carry, value

programs.sol:
"""Predict a negative response mainly to tokens ending in 'st'.

Short spelling fragments receive the largest values. Longer words, leading
spaces/delimiters and common suffix spellings weaken them. Small word lists
calibrate common exceptions, including ranking words and test-related tokens.
Cyrillic ст and several Arabic/East Asian spellings get similar responses;
next/import/assert have modest auxiliary values. Other tokens predict zero.
Only the newest token is used, so this omits contextual variation.
"""
import re

READS = ()
WEAK_WORDS = frozenset('''
just against amongst adjust suggest request exist consist assist contrast
boost twist august exhaust localhost whilst
'''.split())
# Common complete words, rather than isolated spelling fragments.
ST_WORDS = {
    'first': 1.05, 'last': 1.55, 'most': 2.15, 'least': 0.85,
    'best': 2.45, 'worst': 1.95, 'almost': 0.75,
    'must': 1.0, 'post': 1.05, 'host': 1.05, 'lost': 1.05,
    'cost': 1.7, 'west': 1.95, 'east': 1.15,
    'const': 1.1, 'dist': 0.95, 'interest': 0.45,
}
# Short spelling fragments, including Cyrillic vowels followed by ст.
ST_FRAGMENTS = {
    'st': 2.2, 'est': 3.05, 'ast': 2.25, 'ost': 3.05,
    'ist': 1.45, 'ust': 2.7, 'yst': 3.0,
    'ст': 1.95, 'ест': 3.85, 'аст': 2.6, 'ост': 2.4,
    'ист': 1.55, 'уст': 2.8,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = re.sub(r'^[^\w]+', '', token).lstrip('_').lower()
    whitespace = token[:1].isspace()
    delimiter = bool(token) and not token[0].isalnum()
    scale = 1.0
    for ending, factor in [('ing', 0.45), ('ed', 0.5), ('ers', 0.4),
                           ('er', 0.4), ('s', 0.55), ('en', 0.3), ('e', 0.25)]:
        if word.endswith('st' + ending):
            word = word[:-len(ending)]
            scale = factor
            break
    if word in WEAK_WORDS:
        magnitude = 0.05
    elif word.endswith('list'):
        magnitude = 0.25 if delimiter else 0.55
    elif word in ST_WORDS:
        magnitude = ST_WORDS[word]
    elif word == 'test':
        magnitude = 1.65 if whitespace else 2.3
        if token.startswith('/'):
            magnitude = 1.35
        elif delimiter and not whitespace:
            magnitude = 1.85
        elif token == 'Test':
            magnitude = 2.0
    elif word.endswith(('ست', 'スト', '斯特')):
        magnitude = 2.7
    elif word.endswith(('st', 'ст')):
        magnitude = ST_FRAGMENTS.get(word, 2.55)
        if word in ('est', 'ист') and delimiter:
            magnitude = 1.45 if word == 'est' else 0.9
        elif delimiter:
            magnitude -= 0.7
        if word == 'st' and token != 'st' and token != 'ST':
            magnitude = 1.05 if delimiter else 1.2
        if word in ('fest', 'gest'):
            magnitude = 3.7 if not delimiter else 3.2
        magnitude -= 0.3 * max(0, len(word) - 4)
        magnitude = max(0.25, magnitude)
    elif word in ('next', 'import', 'assert'):
        magnitude = {'next': 0.8, 'import': 0.8, 'assert': 0.9}[word]
        if word == 'import' and whitespace:
            magnitude = 0.6
    elif word.endswith(('ste', 'sta', 'sten')) and len(word) < 6:
        magnitude = 0.5
    elif word.endswith(('сти', 'сть', 'еств')) and len(word) <= 4:
        magnitude = 0.85
    else:
        magnitude = 0.0
    return None, -scale * magnitude

