programs.sol:
"""Approximate an i/u spelling-boundary response.

Short vowel fragments react strongly when joined to a preceding vowel, especially
an e. After consonants the response is weaker or negative; bare consonant
fragments and stop/fricative letters depress it further. Longer fragments
react less. Single Cyrillic high vowels and ü use analogous boundary rules;
short Cyrillic у fragments, Arabic waw and Thai long-u signs have smaller
script-specific rules. Other tokens get a near-zero baseline. State keeps
only the preceding token and resets at document boundaries.
The strengths are fitted to spelling classes, not token IDs.
"""
READS = ()
VOWELS = set("aeiouäöüáéíóú")
CYRILLIC_VOWELS = set("аеёиоуыэюя")
# After a vowel, after a vowel-bearing fragment, after a vowel-free fragment.
HIGH_VOWEL_GLYPHS = {
    "у": (0.56, -0.08, -0.35),
    "ю": (0.42, 0.06, 0.00),
    "и": (0.13, -0.05, -0.08),
    "ü": (0.58, -0.06, -0.22),
}

STOP_OR_FRICATIVE_LETTERS = set("bcdfghjkpqstvxz")

# Additive strengths: baseline, vowel join, consonant join,
# vowel-free preceding fragment, preceding stop/fricative letter.
STRENGTHS = {
    "single_i": (0.03, 0.38, 0.02, -0.08, -0.06),
    "single_u": (0.09, 0.69, 0.0, -0.13, -0.18),
    "i_vowel_pair_short": (0.14, 0.56, -0.03, -0.14, -0.09),
    "i_vowel_pair_long": (0.11, 0.31, -0.03, -0.06, -0.03),
    "u_vowel_pair_short": (0.28, 0.64, -0.13, -0.27, -0.17),
    "u_vowel_pair_long": (0.03, 0.36, 0.05, -0.13, -0.07),
    "ure_suffix": (0.26, 0.36, -0.1, -0.3, -0.16),
}

def boundary_value(weights, previous):
    base, vowel, consonant, bare, stop_or_fricative = weights
    end = previous[-1:].lower()
    if end in VOWELS:
        return base + vowel
    if end and end.isalpha():
        base += consonant
        if not any(c.lower() in VOWELS for c in previous):
            base += bare
        if end in STOP_OR_FRICATIVE_LETTERS:
            base += stop_or_fricative
    return base

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    s = token.lower()
    value = 0.0003
    if s.isalpha() and s[0] in 'iu':
        n = len(s)
        if n == 1:
            group = 'single_' + s
        elif s in ('ure', 'ures'):
            group = 'ure_suffix'
        elif s[1] in VOWELS:
            group = s[0] + '_vowel_pair_' + ('short' if n <= 3 else 'long')
        else:
            group = None
        if group is not None:
            value += boundary_value(STRENGTHS[group], previous)
        elif previous[-1:].lower() in VOWELS:
            value += 0.13 if s[0] == 'u' else 0.04
        if previous[-1:].lower() == 'e':
            if s[0] == 'u' and (n == 1 or (n <= 3 and s[1] in VOWELS)):
                value += 0.23
            elif n > 1 and s[0] == 'i' and s[1] in VOWELS:
                value += 0.30
    elif s in HIGH_VOWEL_GLYPHS:
        vowels = VOWELS if s == 'ü' else CYRILLIC_VOWELS
        end = previous[-1:].lower()
        if end and end.isalpha():
            context = (0 if end in vowels else
                       1 if any(c.lower() in vowels for c in previous) else 2)
            value = HIGH_VOWEL_GLYPHS[s][context]
    elif s.startswith('у') and len(s) == 2:
        end = previous[-1:].lower()
        if end in CYRILLIC_VOWELS:
            value = 0.21
        elif end and end.isalpha():
            value = (-0.02 if any(c.lower() in CYRILLIC_VOWELS
                                 for c in previous) else -0.08)
    elif s == 'و' and previous[-1:].isalpha():
        value = 0.20 if previous[-1:] in 'اويىی' else -0.17
    elif s.startswith('ู'):
        value = -0.34 if len(s) == 1 else -0.10
    return (doc, token), float(value)

programs.luna:
"""A sparse spelling cue for a few vowel letters and Latin word endings.

Most activations are near zero; training text showed small positive biases
on isolated u/i pieces and on a few familiar endings. This is not a topic
or meaning detector.
"""

READS = ()

SINGLE_LETTERS = {"u": 0.20, "U": 0.14, "i": 0.074, "I": 0.051}
WORD_ENDINGS = {"ier": 0.046, "ia": 0.054, "ure": 0.015,
                "u": 0.023, "i": 0.016}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in SINGLE_LETTERS:
        return None, SINGLE_LETTERS[token]
    if token and not token.startswith(" "):
        lower = token.lower()
        for ending, value in WORD_ENDINGS.items():
            if lower.endswith(ending):
                return None, value
    return None, 0.0

programs.sol:
"""A spelling-based approximation to a noun-ending detector.

Predict negative activation on -ation, -tion and -sion, strongest when a
known suffix occurs without leading whitespace. Plurals soften the response.
Common lexicalized words and spatial nouns respond less strongly. Include
weaker related -ment/adjectival forms and multilingual noun endings too.
Values are fitted class averages; finer lexical and contextual variation
is deliberately omitted. No state is needed because only this token is read.
"""

READS = ()

LEXICALIZED_WORDS = {
    'information', 'function', 'question', 'option', 'condition', 'transaction'
}
SPATIAL_NOUNS = {'position', 'section', 'direction', 'portion', 'dimension'}
ATION_FRAGMENTS = {
    'ation', 'cation', 'lation', 'ration', 'itation', 'ination',
    'ulation', 'uration', 'uation', 'ication', 'lication', 'ocation',
    'iation', 'ensation', 'vation', 'ilation'
}
DERIVATIONAL_FRAGMENTS = {'ization', 'isation', 'ification'}
OTHER_NOUN_FRAGMENTS = {
    'tion', 'ction', 'ition', 'ution', 'usion', 'lection',
    'raction', 'fection', 'iction', 'uction'
}
FOREIGN_NOUN_ENDINGS = (
    'ación', 'aciones', 'acion', 'ação', 'ações', 'acao', 'ção',
    'zione', 'zioni', 'ация', 'ации', 'ацию', 'ацией', 'аци', 'ция', 'ции',
    'цию', 'цион', 'acji', 'acja', 'ację', 'ーション'
)


def response(token):
    """Return an activation and whether to apply the plural adjustment."""
    word = token.strip().lower().lstrip('._(/-')
    plural = word.endswith('s')
    base = word[:-1] if plural else word
    boundary = token[:1].isspace()

    if base in LEXICALIZED_WORDS:
        return -0.035, False
    if base == 'action' and (boundary or token.strip()[:1].isupper()):
        return -0.035, False
    if base in SPATIAL_NOUNS:
        return -0.462, False
    if word.endswith(FOREIGN_NOUN_ENDINGS):
        return -0.973, False

    if not boundary:
        if base in ATION_FRAGMENTS:
            return -2.733, plural
        if base in DERIVATIONAL_FRAGMENTS:
            return -1.817, plural
        if base in OTHER_NOUN_FRAGMENTS:
            return -1.531, plural
        if base == 'ational':
            return -1.296, False

    if base.endswith(('iation', 'eation', 'pation')):
        return -1.659, plural
    if base.endswith('ation'):
        return -1.245, plural
    if base.endswith('ntion'):
        return -0.562, plural
    if base.endswith('tion'):
        return -1.015, plural
    if base.endswith('sion'):
        return -0.916, plural
    if base.endswith('ion'):
        return -0.295, False
    if base.endswith(('tional', 'tionally')):
        return -0.163, False
    if base.endswith(('hment', 'lment', 'gnment', 'gement', 'vement')):
        return -0.562, plural
    if base.endswith(('pment', 'tment')):
        return -0.405, plural
    if base.endswith('ment'):
        return -0.041, False
    return 0.002, False


def step(carry, prefix, upstream):
    value, plural = response(prefix.token_strings[-1])
    if plural:
        value += 0.322
    return None, float(value)

"""Lexical approximation of a negative engine/plug-in/building-block response.

Recognize the names below even when attached to identifier/path separators.
Plug-ins, engines and widgets have the strongest negative responses. Spelling
and capitalization affect the strength. Two phrases, search engine and std::,
are weaker than their parts suggest. Chinese 'insert' and 'engine' are included;
'basic' has a small positive response. Unrecognized tokens receive zero.
This captures large sparse cues, not weak unrelated effects or richer context.
"""
READS = ()

# Related software parts, plus the Chinese lexical cues described above.
PARTS = {
    'widget': -2.2, 'widgets': -2.3, 'renderer': -1.25,
    'api': -0.45, 'provider': -0.6, 'providers': -0.6,
    'wordpress': -1.0, 'middleware': -0.6, 'codec': -0.65,
    'lexer': -0.6, 'dll': -0.9, 'libs': -0.95, 'sdk': -0.65,
    'backend': -0.7, 'handler': -0.55, 'handlers': -0.5,
    'adapter': -0.3, 'theme': -0.5, 'bucket': -0.55,
    'bundle': -0.2, 'driver': -0.3, 'drivers': -0.3,
    'addons': -0.9, 'dependencies': -0.3,
    '插': -1.3, '引擎': -2.5,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    name = text.lstrip('._-/\\(').lower()
    spaced = token[:1].isspace()
    capital = any(c.isupper() for c in text)
    separator = bool(text) and text[0] in '._-/\\('
    previous = ''
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2].strip().lower()

    value = PARTS.get(name, 0.0)
    if text == '::':
        value = -0.36 if previous in {'std', '(std'} else -0.74
        if previous == '.py':
            value = -0.87
    elif name == 'plugin':
        value = -3.05 if spaced else -3.55
        if capital or text.startswith('-'):
            value = -3.6 if spaced else -4.2
    elif name == 'plugins':
        value = -3.0 if not capital else -3.3
        if text.startswith(('.', '/')):
            value = -3.55
    elif name in {'engine', 'engines'}:
        value = -1.65 if spaced and not capital else -2.65
        if name == 'engines':
            value = -1.15
        if previous == 'search':
            value = -0.65
    elif name in {'module', 'modules'}:
        value = -0.3 if spaced else -0.5
        if text.startswith('_'):
            value = -1.22 if name == 'modules' else -0.57
    elif name == 'editor':
        value = -0.45 if spaced else -0.7
        if separator:
            value = -1.0
    elif name in {'extension', 'extensions', 'ext'}:
        value = -0.75 if spaced else -1.2
        if name == 'extensions' and not spaced:
            value = -1.8
        if name == 'ext':
            value = -0.45 if spaced else -0.7
    elif name in {'lib', 'library', 'libraries'}:
        value = -0.45 if name == 'lib' else -0.2
        if text.startswith('/') and name == 'lib':
            value = -0.86
    elif name == 'basic':
        value = 0.65 if capital else 0.45
    elif name == 'packages':
        value = -0.75 if text.startswith('-') else -0.25
        if text.startswith('/'):
            value = 0.0
    return None, value

programs.haiku:
"""Layer-0 MLP down_proj component 1981: a "bounds and comparisons" detector.

It fires on the words and symbols that set a quantity against a level, a range
or a threshold: "value", "range", "level", "threshold", "between", "within",
"above", "below", "than" (in "higher than"), and identifiers containing
"value" or "range" (such as "_value"), "at" (in "at 4 C", "at constant
pressure"), comparison signs such as " <" and " >=", and the "to" of "equal to"
and the "of" of "range of" / "levels of". It is nearly silent elsewhere, and
on "at" after look/looking ("look at the issue").

The program is a fixed lexicon with graded strengths, plus two short
context rules. It keeps no state.
"""

READS = ()

LOOK_VERBS = {"look", "looks", "looked", "looking"}
COMPARATIVES = {"higher", "lower", "greater", "more", "less", "fewer", "larger",
                "smaller", "bigger", "better", "worse", "faster", "slower"}

# Strength of each word (lower-cased, spaces stripped).
STRONG = {"value", "values", "range", "ranges", "threshold", "within", "between",
          "levels", "whether", "minimum", "maximum"}
MEDIUM = {"level", "around", "below", "above", "than", "min", "max", "limit",
          "exceeds", "outside", "beyond", "least", "lowest", "greater"}
WEAK = {"at", "lower", "higher", "near", "inside", "about", "reach", "reached",
        "achieve", "achieved", "low", "high", "point"}
# Comparison signs, as the tokens are written (with a leading space or alone).
SIGNS = {" <": 0.5, " >": 0.5, " <=": 0.5, " >=": 0.5, " ≤": 0.5, " ≥": 0.5,
         "<": 0.15, ">": 0.15}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if "value" in word or "range" in word:
        value = 0.7
    elif raw in SIGNS:
        value = SIGNS[raw]
    elif word in STRONG:
        value = 0.75
    elif word in MEDIUM:
        value = 0.5
    elif word in WEAK:
        value = 0.3
    else:
        value = 0.0
    if word == "at" and prev in LOOK_VERBS:
        value = 0.0
    if word == "than" and prev not in COMPARATIVES:
        value = 0.3
    if word == "to" and prev in {"equal", "or"}:
        value = 0.7
    if word == "of" and prev in {"range", "levels", "level", "values", "value"}:
        value = 0.6
    return carry, float(value)

programs.sol:
"""Recognize configuration identifiers and text/string data vocabulary.

Negative responses are strongest for config, text widgets and text-access
methods. Punctuation, case and the previous token help distinguish code
identifiers from prose or LaTeX commands. Unrecognized tokens predict zero.
"""
READS = ()

TEXT_FIELDS = {'textfield', 'jtextfield', 'textinput'}
TEXT_DISPLAY = {
    'textview', 'edittext', 'gettext', 'settext', 'createtextnode',
    'textalign', 'jlabel', 'textarea', 'stringvalue',
}
FORM_WIDGETS = {
    'textbox', 'imageview', 'radiobutton', 'addcomponent',
    'addgroup', 'addeventlistener', 'addactionlistener',
}
TYPED_IO = {
    verb + kind
    for verb in ('get', 'set', 'read', 'write')
    for kind in ('file', 'int', 'long', 'boolean', 'object')
}


def response(token, previous):
    s = token.strip()
    word = s.lstrip('._-:(/[<')
    w = word.lower()
    spaced = token[:1].isspace()
    capital = word[:1].isupper()
    mark = s[:1]
    if w in {'config', 'getconfig', 'setconfig', 'configs'}:
        if mark in {'(', '_', '-'}:
            return -0.98
        return -1.35 if s == 'config' and not spaced else -1.18
    if w in {'configuration', 'configured', 'configure'}:
        return -0.30
    if w == 'text':
        if mark in {'.', '/', '_'}:
            return -0.90 if capital else -0.78
        if not spaced and capital:
            return -0.75
        if previous.rstrip().endswith('\\'):
            return -0.28  # LaTeX's \text command.
        if not spaced and any(c in previous for c in '\"\''):
            return -0.73
        return -0.43
    if w == 'string':
        if mark == '.':
            return -0.65
        if mark in {'<', '[', '(', '_'}:
            return -0.30
        return -0.44 if capital or not spaced else -0.20
    if w == 'str':
        if mark in {'[', '_'}:
            return -0.25
        if spaced or word != 'str':
            return -0.12
        return -0.04 if previous[-1:].isalpha() else -0.33
    if w == 'varchar':
        return -0.58
    if w in TEXT_FIELDS:
        return -1.30
    if w in TEXT_DISPLAY:
        return -0.85
    if w in FORM_WIDGETS:
        return -0.60
    if w in {'getstring', 'setstring'}:
        return -0.95 if word[:1].islower() else -0.35
    if w in TYPED_IO:
        return -0.55
    if w in {'stringbuilder', 'strcmp', 'strcpy', 'substring'}:
        return -0.38
    if w in {'txt', 'tostring'}:
        return -0.25
    if w == 'object':
        return -0.33 if capital or not spaced else -0.18
    if w in {'type', 'settings', 'options', 'conf'}:
        return -0.15
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), response(token, previous)

programs.haiku:
"""layers.0.mlp.down_proj:1983 — a "config / string-type word" detector.

This component is almost silent everywhere, but it has a clear, negative response to
the current token when that token is a word from software code about configuration
or about text/string types:

- "config" itself (and its forms: _config, .config, getConfig, -config, /config, Config)
  gives the strongest response, about -1.1.
- "text", "string", "varchar" (and words ending in them, e.g. _text, DateString) give a
  moderate response, about -0.4.
- weaker type-ish words (str, char, object, type, column, datetime, integer, settings)
  give about -0.2.
- "configuration" and "configure(d)" give a weak response, about -0.3.
- The chat tool-call tags (<tool_call>, <tool_response>) give about -0.2.
- A few keyword tokens (typeof, kwargs) go slightly positive.

Everything else predicts 0. The program looks only at the current token, so it needs no
memory between positions. Its predictions are the activation (what the model adds to
the residual stream, scaled as in the component), so it is written in those units.
"""

CONFIG_STRONG = -1.1      # "config" in any spelling
CONFIG_WEAK = -0.3        # "configuration", "configured", "configure"
TEXT_TYPE = -0.4          # string / text / varchar, and words ending in them
TYPE_WEAK = -0.2          # str, char, object, type, column, datetime, integer, settings
TOOL_TAG = -0.2           # <tool_call>, <tool_response>
KEYWORD_POS = 0.4         # typeof, kwargs

TEXT_WORDS = {"string", "text", "varchar"}
TYPE_WORDS = {"str", "char", "object", "type", "datetime", "integer", "column", "settings"}
KEYWORDS = {"typeof", "kwargs"}
TOOL_TAGS = {"<tool_call>", "<tool_response>"}


def word_of(token: str) -> str:
    """The token as a bare lowercase word: no case, no leading space, _, ., -, / or (."""
    return token.strip().strip("_.-/(").lower()


def value_of(word: str) -> float:
    if "configur" in word:
        return CONFIG_WEAK
    if "config" in word:
        return CONFIG_STRONG
    if word == "cfg":
        return -0.4
    if word in TEXT_WORDS or word.endswith("string") or word.endswith("text"):
        return TEXT_TYPE
    if word in TYPE_WORDS:
        return TYPE_WEAK
    if word in KEYWORDS:
        return KEYWORD_POS
    if word in TOOL_TAGS:
        return TOOL_TAG
    return 0.0


READS = ()


def step(carry, prefix, upstream):
    # The current token is the last one in the prefix; no state is carried.
    return None, float(value_of(word_of(prefix.token_strings[-1])))
